typedef struct SharkSslHSParam
{
   union
   {
      #if SHARKSSL_TLS_1_2
      struct
      {
         U8 clientRandom[SHARKSSL_RANDOM_LEN];
         U8 serverRandom[SHARKSSL_RANDOM_LEN];
         #if SHARKSSL_PSA_CONSUMER
         /* Derived before ChangeCipherSpec; transferred to the active record contexts. */
         psa_key_id_t nextRRecordKey;
         psa_key_id_t nextWRecordKey;
         #if (SHARKSSL_USE_CHACHA20 && SHARKSSL_USE_POLY1305)
         U8 nextRIV[SHARKSSL_TLS_AEAD_NONCE_LEN];
         U8 nextWIV[SHARKSSL_TLS_AEAD_NONCE_LEN];
         #else
         U8 nextRIV[SHARKSSL_TLS_1_2_AES_GCM_FIXED_IV_LEN];
         U8 nextWIV[SHARKSSL_TLS_1_2_AES_GCM_FIXED_IV_LEN];
         #endif
         #else
         U8 masterSecret[SHARKSSL_MASTER_SECRET_LEN];
         U8 sharedSecret[2 * (SHARKSSL_MAX_DIGEST_LEN + SHARKSSL_MAX_KEY_LEN + SHARKSSL_MAX_BLOCK_LEN) + SHARKSSL_MAX_DIGEST_LEN];
         #endif
         #if SHARKSSL_USE_SHA_512
         SharkSslSha512Ctx sha512Ctx;
         #endif
         #if SHARKSSL_ENABLE_DHE_RSA
         SharkSslDHParam dhParam;
         #endif
      } tls12;
      #endif
      #if SHARKSSL_TLS_1_3
      struct
      {
         #if (!SHARKSSL_PSA_CONSUMER_SECRET_HANDLES)
         U8 HSSecret[SHARKSSL_TLS_1_3_MAX_DIGEST_LENGTH];
         #endif
         U8 srvHSTraffic[SHARKSSL_TLS_1_3_MAX_DIGEST_LENGTH];
         #if (!SHARKSSL_PSA_CONSUMER_SECRET_HANDLES)
         U8 cliHSTraffic[SHARKSSL_TLS_1_3_MAX_DIGEST_LENGTH];
         #endif
         #if SHARKSSL_PSA_CONSUMER_SECRET_HANDLES
         psa_key_id_t psaHSSecret;
         psa_key_id_t psaSrvHSTraffic;
         psa_key_id_t psaCliHSTraffic;
         #endif
         #if SHARKSSL_USE_ECC
         #if (!SHARKSSL_PSA_CONSUMER)
         #if SHARKSSL_ECC_USE_CURVE448
         U8 privKeyCURVE448[SHARKSSL_CURVE448_POINTLEN];
         #endif
         #if SHARKSSL_ECC_USE_CURVE25519
         U8 privKeyCURVE25519[SHARKSSL_CURVE25519_POINTLEN];
         #endif
         #if SHARKSSL_ECC_USE_SECP384R1
         U8 privKeySECP384R1[SHARKSSL_SECP384R1_POINTLEN];
         #endif
         #if SHARKSSL_ECC_USE_SECP256R1
         U8 privKeySECP256R1[SHARKSSL_SECP256R1_POINTLEN];
         #endif
         #if SHARKSSL_ECC_USE_BRAINPOOLP512R1
         U8 privKeyBRAINPOOL[SHARKSSL_BRAINPOOLP512R1_POINTLEN];
         #elif SHARKSSL_ECC_USE_BRAINPOOLP384R1
         U8 privKeyBRAINPOOL[SHARKSSL_BRAINPOOLP384R1_POINTLEN];
         #elif SHARKSSL_ECC_USE_BRAINPOOLP256R1
         U8 privKeyBRAINPOOL[SHARKSSL_BRAINPOOLP256R1_POINTLEN];
         #endif
         #endif  /* !SHARKSSL_PSA_CONSUMER */
         #endif  /* SHARKSSL_USE_ECC */
         #if (SHARKSSL_ENABLE_CLIENT_AUTH || (SHARKSSL_SSL_SERVER_CODE && SHARKSSL_ENABLE_EDDSA && SHARKSSL_PSA_CONSUMER))
         U16 signatureScheme;
         #endif
         #if SHARKSSL_SSL_SERVER_CODE
         U16 grpLen;
         U8 *grpPtr;
         #if SHARKSSL_ENABLE_SESSION_CACHE
         U8 *pskBinder;  /* first PskBinderEntry length byte */
         U16 pskIdentity;
         U8  pskBinderLen;
         U8  pskFlags;
         #endif
         #endif
         #if SHARKSSL_SSL_CLIENT_CODE
         U8 offeredExtensions;  /* TLS 1.3 ClientHello extensions which can solicit a server response */
         #endif
         #if SHARKSSL_ENABLE_HELLO_RETRY_REQUEST
         U16 hrrGroup;  /* group requested in HelloRetryRequest */
         #if SHARKSSL_SSL_SERVER_CODE
         U8  hrrClientHelloHash[SHARKSSL_SHA256_HASH_LEN];  /* immutable ClientHello fields */
         #endif
         U8  hrrState;  /* 0 before HRR; server: 1 after message_hash; client: 1 pending CH2, 2 sent */
         #endif
      } tls13;
      #endif
   } prot;
   #if SHARKSSL_RANDOMIZE_EXTENSIONS
   #define SHARKSSL_MAX_EXTENSIONS 8  /* multiple of 4 to keep alignment */
   U32 extState; 
   U8  extIndex[SHARKSSL_MAX_EXTENSIONS];
   #endif
   #if SHARKSSL_PSA_CONSUMER
   psa_hash_operation_t *psaTranscript;
   #if SHARKSSL_USE_SHA_384
   psa_hash_operation_t *psaTranscript384;
   #endif
   U8 psaHashFailed;
   #else
   SharkSslSha256Ctx sha256Ctx;
   #if SHARKSSL_USE_SHA_384
   SharkSslSha384Ctx sha384Ctx;
   #endif
   #endif
   #if (SHARKSSL_ENABLE_RSA || SHARKSSL_ENABLE_ECDSA)
   SharkSslCertParsed *certParsed;  /* the selected cert */
   SharkSslCertKey     certKey;     /* points to cert's key */
   SharkSslCertParam   certParam;   /* peer's cert */
   SharkSslSignParam   signParam;
   #endif
   #if (SHARKSSL_ENABLE_ECDHE_RSA || SHARKSSL_ENABLE_ECDHE_ECDSA)
   SharkSslECDHParam   ecdhParam;
   #endif
   SharkSslCipherSuite *cipherSuite;
   #if SHARKSSL_ENABLE_SNI
   U8 SNI_match:1;
   #endif

   /* TO BE KEPT AT THE END OF THE STRUCT! */
   #if (SHARKSSL_TLS_1_3 && SHARKSSL_ENABLE_POST_HANDSHAKE_AUTH && (!SHARKSSL_PSA_CONSUMER))
   union
   {
      SharkSslSha256Ctx sha256Ctx;
      #if SHARKSSL_USE_SHA_384
      SharkSslSha384Ctx sha384Ctx;
      #endif
   } phaCtx;
   #endif
} SharkSslHSParam;


