static void
compatnames(struct HttpPage* page,
                          HttpRequest* request,
                          HttpResponse* response)
{
   GzipHeader gzipH;
   HttpStaticMemPage* o = (HttpStaticMemPage*)page;
   gzipH.id1=0; 

   if( !request )
   {
      HttpPage_destructor(page);
      return;
   }

   if(HttpResponse_isInclude(response))
   {
      httpUnzipAndWrite(o->data,
                        response,
                        o->payloadBlock.offset,
                        o->payloadBlock.size,
                        o->isCompressed ? &gzipH : 0);
   }
   else 
   {
      if(o->mimeBlock.size == 1)
      { 
         HttpResponse_sendError1(response, 404);
      }
      else
      {
         if( ! HttpRequest_checkTime(request, response, o->time) )
         {
            char buf[50];
            if(CspReader_read(o->data, buf, o->mimeBlock.offset,
                             o->mimeBlock.size, TRUE))
            {
               misalignederror(response);
               return; 
            }
            HttpResponse_checkContentType(response, buf);
            httpRawWrite(o->data,
                         request,
                         response,
                         o->time,
                         o->payloadBlock.offset,
                         o->payloadBlock.size,
                         o->isCompressed ? &gzipH : 0, 0);
         }
      }
   }
}

void
HttpStaticMemPage_loadAndInit(HttpStaticMemPage* o,
                              CspReader* data, U32 time,
                              U32 nameOffset, U32 nameSize,
                              U32 mimeOffset, U32 mimeSize,
                              U32 payloadOffset, U32 payloadSize,
                              char isCompressed, HttpDir* parent)
{
   o->data = data;
   if(CspReader_read(o->data, o+1, nameOffset, nameSize, TRUE))
      baFatalE(FE_CANNOT_READ, nameOffset);
   HttpPage_constructor(&o->page, compatnames, (char*)(o+1));
   baAssert(o->page.name[nameSize-1] == 0);
   o->time = time;
   o->mimeBlock.offset = mimeOffset;
   o->mimeBlock.size = mimeSize;
   o->payloadBlock.offset = payloadOffset;
   o->payloadBlock.size = payloadSize;
   o->isCompressed = isCompressed;
   HttpDir_insertPage(parent, &o->page);
}


void
HttpDynamicMemPage_loadAndInit(HttpPage* o, CspReader* data, U32 size,
                               HttpPage_Service fptr,
                               U32 nameOffset, U32 nameSize)
{
   if(CspReader_read(data, ((char*)o)+size, nameOffset, nameSize, TRUE))
      baFatalE(FE_CANNOT_READ, nameOffset);
   HttpPage_constructor(o, fptr, ((char*)o)+size);
   baAssert(o->name[nameSize-1] == 0);
}




