static void
writeswinc(HttpAsynchReq* o)
{
   SoDisp* disp=SoDispCon_getDispatcher((SoDispCon*)o);
   if(SoDispCon_recEvActive((SoDispCon*)o))
      SoDisp_deactivateRec(disp,(SoDispCon*)o);
   if(SoDispCon_dispatcherHasCon((SoDispCon*)o))
      SoDisp_removeConnection(disp,(SoDispCon*)o);
}


static S32
restorecurrent(HttpAsynchReq* o, S32 size)
{
   size = HttpConnection_readData(
      (HttpConnection*)o, o->buffer + o->offset, size);
   if(size < 0)
   {
      writeswinc(o);
      o->data(o,0, -1); 
   }
   else
      o->offset += size;
   return size;
}



static void
prefetchparameters(HttpAsynchReq* o, BaBool* isTerminatedPtr)
{
   S32 size;
   do
   { 
      size = (S32)(o->bufferSize - o->offset);
      if(size > o->packetSizeLeft)
         size = (S32)o->packetSizeLeft;
      size = restorecurrent(o, size);
      if(size > 0)
      {
         o->packetSizeLeft -= size;
         if(o->packetSizeLeft == 0)
         {
            o->data(o,o->buffer, (S32)o->offset);
            if(*isTerminatedPtr) return;
            o->data(o,0, 0);
            if( ! *isTerminatedPtr )
            {  
               writeswinc(o);
            }
            return;
         }
         if(o->offset == o->bufferSize)
         {
            o->data(o, o->buffer, (S32)o->offset);
            if(*isTerminatedPtr) return;
            o->offset=0;
         }
      }
   } while(size > 0 && HttpConnection_hasMoreData((HttpConnection*)o));
}


