void
SoDispCon_internalAllocAsynchBuf(SoDispCon* con, AllocAsynchBufArgs* args)
{
   NonBlockingSendBuf* buf;
    
   if(con->sslData &&
      ((NonBlockingSendBuf*)con->sslData)->maxBufLen>=args->size)
   {
      buf = (NonBlockingSendBuf*)con->sslData;
      args->size=buf->maxBufLen;
   }
   else
   {
      size_t size =  sizeof(NonBlockingSendBuf)+args->size;
      if(con->sslData) 
         SoDispCon_releaseAsyncBuf(con);
      buf = (NonBlockingSendBuf*)baMalloc(size);
      if(buf)
      {
         size -= sizeof(NonBlockingSendBuf);
         args->size = buf->maxBufLen = (int)size;
         con->sslData = buf;
      }
      else
         args->retVal = 0; 
   }
   if(buf)
   {
      args->retVal = buf->buf;
      buf->cursor = buf->bufLen = 0;
   }
}



static int
mcbsp3hwmod(SoDispCon* con, int len)
{
   if(con->sslData)  
   {
      BaBool isTerminated=FALSE;
      ThreadMutex* m=0;
      NonBlockingSendBuf* buf = (NonBlockingSendBuf*)con->sslData;
      if( ! buf->bufLen )
      {
         if( ! len ) 
            return 1; 

         
         baAssert(buf->maxBufLen >= len);

         buf->bufLen = len; 
      }
      len = buf->bufLen - buf->cursor;
      HttpSocket_send(&con->httpSocket, m, &isTerminated,
                      buf->buf+buf->cursor, len, &len);
      (void)isTerminated;
      if(len < 0 || !SoDispCon_isValid(con))
         return E_SOCKET_WRITE_FAILED; 
      buf->cursor+=len;
      baAssert(buf->cursor <= buf->bufLen);
      if(buf->cursor == buf->bufLen)
      {
         buf->cursor = buf->bufLen = 0; 
         return 1; 
      }
      return 0; 
   }
   return 1; 
}


void
SoDispCon_releaseAsyncBuf(SoDispCon* con)
{
   if(con->sslData)
   {
      baFree(con->sslData);
      con->sslData=0;
   }
}


static int
uart0writel(SoDispCon* con,
                    ThreadMutex* m,
                    SoDispCon_ExType s,
                    void* data,
                    int len)
{
   int status;
   BaBool isTerminated=FALSE;

   if( ! SoDispCon_isValid(con) )
   {
      baAssert( ! con->sslData );
      if(s == SoDispCon_GetSharkSslCon)
      {
         if(data) *((void**)data) = 0;
         return FALSE;
      }
      if(s == SoDispCon_ExTypeMoveCon)
         goto L_ExTypeMoveCon;
      return -1;
   }

   switch(s)
   {
      case SoDispCon_ExTypeRead:
         if( SoDispCon_hasMoreData(con) )
         {
            if(con->recTermPtr) 
               return E_SOCKET_READ_FAILED;
            con->recTermPtr=&isTerminated;
            status = SoDispCon_platReadData(con,m,&isTerminated,data,len);
            if(isTerminated)
               return E_SOCKET_READ_FAILED;
            con->recTermPtr=0;
            if( ! SoDispCon_socketHasNonBlockData(con) ||
                (status <= 0 && !SoDispCon_readEmptyDgram(con)))
               SoDispCon_clearHasMoreData(con);
            return status;
         }
         return 0;

      case SoDispCon_ExTypeWrite:
         if(con->sendTermPtr) 
            return E_SOCKET_WRITE_FAILED;
         con->sendTermPtr=&isTerminated;
         
         HttpSocket_send(&con->httpSocket,m,&isTerminated, data?data:
                         ((NonBlockingSendBuf*)con->sslData)->buf,len,&status);
         if(isTerminated)
            return E_SOCKET_WRITE_FAILED;
         con->sendTermPtr=0;
         return status < 0 ? E_SOCKET_WRITE_FAILED : status;

      case SoDispCon_GetSharkSslCon:
         if(data) *((void**)data) = 0;
         return FALSE;

      case SoDispCon_ExTypeClose:
         if( con->sendTermPtr )
         {
            *con->sendTermPtr=TRUE;
            con->sendTermPtr=0;
         }
         if( con->recTermPtr )
         {
            *con->recTermPtr=TRUE;
            con->recTermPtr=0;
         }
#ifdef BA_LWIP
         
         HttpSocket_close(&con->httpSocket);
#endif
         SoDispCon_releaseAsyncBuf(con);
         return 0;

      case SoDispCon_ExTypeMoveCon:
      L_ExTypeMoveCon:
         baAssert(con->exec == uart0writel);
         ((SoDispCon*)data)->exec=uart0writel;
         ((SoDispCon*)data)->sslData= con->sslData; 
         con->sslData=0;
         return 0;

      case SoDispCon_ExTypeAllocAsynchBuf:
         SoDispCon_internalAllocAsynchBuf(con, (AllocAsynchBufArgs*)data);
         return 0;

      case SoDispCon_ExTypeAsyncReady:
         return mcbsp3hwmod(con, len);

      case SoDispCon_ExTypeIdle:
         SoDispCon_releaseAsyncBuf(con);
         return TRUE;
   }
   baAssert(0);
   return -1;
}

