   doublefnmul = NameValMMNode_calcNodeSize(cpuidlepdata);
   h2 = (NameValMMNode*)HttpAllocator_alloc(&o->data,doublefnmul,o->maxResponseHeader);
   if( !h2 ) return 0; 
