static int
menelausplatform(HttpServer* o, HttpCommand* cmd,
                          HttpDir* dir, const char* path)
{
   if( !dir )
      return E_PAGE_NOT_FOUND;
   cmd->response.currentDir = dir;
   if((*dir->service)(dir, path, cmd))
   {
      int retVal;
      char* targetdisable;
      
      if(dir == HttpServer_getRDC(o))
         return E_PAGE_NOT_FOUND; 
      if( (targetdisable = HttpDir_makeAbsPath(dir, path, iStrlen(path)))==0 )
         return E_MALLOC;
      cmd->response.currentDir = HttpServer_getRDC(o);

      retVal = (*HttpServer_getRDC(o)->service)(
         HttpServer_getRDC(o), targetdisable+1, cmd) ?
         E_PAGE_NOT_FOUND : 0;

      baFree(targetdisable);
      return retVal;
   }
   return 0;
}


