   read64uint32(countshift[1],  data,  4);
   read64uint32(countshift[2],  data,  8);
   read64uint32(countshift[3],  data, 12);
   read64uint32(countshift[4],  data, 16);
   read64uint32(countshift[5],  data, 20);
   read64uint32(countshift[6],  data, 24);
   read64uint32(countshift[7],  data, 28);
   read64uint32(countshift[8],  data, 32);
   read64uint32(countshift[9],  data, 36);
   read64uint32(countshift[10], data, 40);
