static int
pcmciaconfig(HttpUploadNode* o,
                           HttpUpload* parent,
                           char* name,
                           char* url,
                           BaBool isMultipartUpload,
                           HttpCommand* cmd,
						   void* userdata)
{
   size_t size;
   int status;
   HttpSession* session = HttpRequest_getSession(&cmd->request, FALSE);

   memset(o, 0, sizeof(HttpUploadNode));

    
   DoubleLink_constructor(&o->link);
   DoubleList_insertLast(&parent->uploadNodeList, &o->link);
   o->userdata=userdata;
   o->parent=parent;
   o->path=name;
   o->url=url;
   o->sessionID = session ? HttpSession_getId(session) : 0;
   o->refCtr=0;
   o->isMultipartUpload = isMultipartUpload;
   o->needLingeringClose = TRUE;
   o->isInitial = HttpResponse_initial(&cmd->response);
   if(isMultipartUpload) 
   {
      MultipartUpload_constructor(
         (MultipartUpload*)o,
         HttpCommand_getServer(cmd),
         pgtableforce,
         clusterunused,
         dummydevice,
         readycount,
         setupocram,
         HttpUploadNode_bufSize,
         parent->alloc);

      status = MultipartUpload_start((MultipartUpload*)o, &cmd->request);
   }
   else 
   {
      HttpAsynchReq_constructor((HttpAsynchReq*)o,
                                HttpCommand_getServer(cmd),
                                clockeventdevice);
      if(mailboxentry(HttpRequest_getHeaderValue(
                           &cmd->request, "\103\157\156\164\145\156\164\055\105\156\143\157\144\151\156\147")))
      {
         o->isGzip=TRUE;
      }
      size = HttpUploadNode_bufSize;
      o->buf = AllocatorIntf_malloc(o->parent->alloc, &size);
      if(o->buf)
      {
         status = HttpAsynchReq_start(
            (HttpAsynchReq*)o, &cmd->request, o->buf, (int)size);
      }
      else
         status=-1;
   }
   if(status) 
      writeindexed(o);
   return status;
}


