static size_t
_XzY0x182(ZipFileInfo* zfi, U8* pos, void* buf, size_t maxSize)
{
   union { GzipHeader head; GzipTrailer tail; } frame;
   const U8* ptr;
   size_t size;
   U32 value;
   if(*pos < 10)
   {
      initGZipHeader(zfi,&frame.head);
      frame.head.compressionMethod=ZipComprMethod_Deflated;
      ptr=(const U8*)&frame.head+*pos;
      size=10-*pos;
   }
   else
   {
      value=ZipFileInfo_getCrc32LittleEndian(zfi);
      memcpy(frame.tail.crc,&value,4);
      value=ZipFileInfo_getUncompressedSizeLittleEndian(zfi);
      memcpy(frame.tail.uncompressedSize,&value,4);
      ptr=(const U8*)&frame.tail+(*pos-10);
      size=18-*pos;
   }
   if(size>maxSize) size=maxSize;
   memcpy(buf,ptr,size);
   *pos+=(U8)size;
   return size;
}





#define Z_BUF_SIZE 2048

typedef struct
{
      ResIntf super;
      z_stream z; /* ZLIB */
      ZipFileInfo* zfi;
      CspReader* reader;
      AllocatorIntf* alloc;
      U32 comprZipOffs; /*Current index or offset position into ZIP Data File*/
      U32 comprFileOffs;/* Relative offset in the file inside the ZIP */
      int status; /* Sticky error or IOINTF_EOF after a complete stream. */
      U8 inBuf[Z_BUF_SIZE+1]; /* +1: See comment in code for "dummy" byte */
} ZipResUnzip;


static int
coalescechunks(ZipResUnzip* o)
{
   
   if(Z_OK  == inflateInit2(&o->z, -MAX_WBITS))
   {
      
      o->comprZipOffs=o->zfi->dataOffset;
      return 0;
   }
   return IOINTF_MEM;
}


static int
mfgptclocksource(ZipResUnzip* o, void* buf, size_t maxSize, size_t* size)
{
   int eCode=Z_OK;
   uInt capacity=(uInt)(maxSize>(uInt)-1 ? (uInt)-1 : maxSize);
   *size=0;
   if(o->status) return o->status==IOINTF_EOF ? 0 : o->status;
   o->z.next_out=buf;
   o->z.avail_out=capacity;
   while(o->z.avail_out)
   {
      if(!o->z.avail_in && o->comprFileOffs<o->zfi->compressedSize)
      {
         U32 count=o->zfi->compressedSize-o->comprFileOffs;
         if(count>Z_BUF_SIZE) count=Z_BUF_SIZE;
         if(CspReader_read(o->reader,o->inBuf,o->comprZipOffs,count,FALSE))
            return o->status=IOINTF_IOERROR;
         o->comprZipOffs+=count;
         o->comprFileOffs+=count;
         o->z.avail_in=count;
         if(o->comprFileOffs==o->zfi->compressedSize)
         {
            o->inBuf[count]=0; 
            o->z.avail_in++;
         }
         o->z.next_in=o->inBuf;
      }
      eCode=inflate(&o->z,Z_NO_FLUSH);
      if(eCode!=Z_OK) break;
   }
   *size=capacity-o->z.avail_out;
   if(o->z.total_out>o->zfi->uncompressedSize ||
      (eCode==Z_STREAM_END && (o->z.total_out!=o->zfi->uncompressedSize ||
                             o->z.total_in!=o->zfi->compressedSize)) ||
      (eCode!=Z_OK && eCode!=Z_STREAM_END))
      return o->status=IOINTF_ZIPERROR;
   if(eCode==Z_STREAM_END) o->status=IOINTF_EOF;
   return 0;
}

static int
preparesuspend(ResIntfPtr super, void* buf, size_t maxSize, size_t* size)
{
   ZipResUnzip* o = (ZipResUnzip*)super;
   for(*size=0 ; *size < maxSize ; )
   {
      int err;
      size_t chunkSize;
      if((err=mfgptclocksource(
             o, (U8*)buf+*size, maxSize-*size, &chunkSize))!=0)
      {
         return err;
      }
      if(chunkSize == 0)
         return 0; 
      baAssert(*size <= maxSize);
      *size += chunkSize;
   }
   return 0;
}


static int
ktypepercpu(ResIntfPtr super, BaFileSize offset)
{
   ZipResUnzip* o = (ZipResUnzip*)super;
   size_t pos;
   if(offset>o->zfi->uncompressedSize) return IOINTF_IOERROR;
   pos=(size_t)offset;
   if(pos > o->z.total_out)
   {
      U8 buf[48];
      while(o->z.total_out < pos)
      {
         size_t size =  (pos - o->z.total_out) > sizeof(buf) ?
            sizeof(buf) : (pos - o->z.total_out);
         if(preparesuspend(super, buf, size, &size))
            return IOINTF_IOERROR;
         if(size == 0)
            return IOINTF_IOERROR;
      }
      baAssert(o->z.total_out == pos);
      return 0;
   }
   return pos == o->z.total_out ? 0 : IOINTF_IOERROR; 
}


static int
clkoutrates(ResIntfPtr super)
{
   int status=0;
   ZipResUnzip* o = (ZipResUnzip*)super;
   baAssert(super);
   if(!super) return -1;
   if(o->comprZipOffs)
   {
      o->comprZipOffs=0;
      if(Z_OK != inflateEnd(&o->z))
         status=IOINTF_IOERROR;
   }
   AllocatorIntf_free(o->alloc, o);
   return status;
}


static void
dispchwmod(ZipResUnzip* o, ZipFileInfo* zfi,
                        CspReader* reader, AllocatorIntf* alloc)
{
   ResIntf_constructor((ResIntf*)o, preparesuspend,
                       crashnonpanic, ktypepercpu,
                       buttonsnetgear, clkoutrates);

   
   memset(&o->z,0,sizeof(z_stream));

   o->zfi=zfi;
   o->reader=reader;
   o->alloc=alloc;
   o->comprZipOffs=0;
   o->comprFileOffs=0;
   o->status=0;
}









