static void
pciercxcfg031(AuthUserList* o,
                         UserIntf* userDb,
                         AuthInfo* info)
{
   memset(o, 0, sizeof(AuthUserList));
   DoubleList_constructor(&o->list);
   o->username = info->username ? baStrdup(info->username) : 0;
   if(o->username)
   {
      SplayTreeNode_constructor((SplayTreeNode*)o, o->username);
      o->password = *info->password ? baStrdup((char*)info->password) : 0;
      if(o->password)
      {
         o->server=HttpCommand_getServer(info->cmd);
         SplayTree_insert(&o->server->authUserTree, (SplayTreeNode*)o);
         o->userDb = userDb;
         return;
      }
      
      baFree(o->username);
      o->username=0;
   }
}


static void
au1200intclknames(AuthUserList* o)
{
   baAssert(DoubleList_isEmpty(&o->list));
   SplayTree_remove(&o->server->authUserTree, (SplayTreeNode*)o);
   baFree(o->password);
   baFree(o->username);
}



static int
singleftouiz(AuthUserList* o, AuthInfo* info)
{
   AuthUserListEnumerator e;
   AuthenticatedUser* au;

   AuthUserListEnumerator_constructor(&e, o);
   for(au = AuthUserListEnumerator_getElement(&e);
       au ;
       au = AuthUserListEnumerator_nextElement(&e))
   {
      HttpSession* s = AuthenticatedUser_getSession(au);
      if((HttpSession_getUseCounter(s)<1 || info->recycle) && !s->lockCounter)
      {
         
         DoubleLink_unlink(&au->dlink);
         HttpSession_terminate(s);
         baAssert(o->listLen > 0);
         o->listLen--;
         return 0;
      }
   }
   return -1;
}



void
AuthUserList_termIfEmpty(AuthUserList* o)
{
   if(o) 
   {
      baAssert(o->listLen >= 0);
      if(DoubleList_isEmpty(&o->list))
      {
         baAssert(o->listLen == 0);
         au1200intclknames(o);
         baFree(o);
      }
   }
}


static void
commonsuspend(AuthUserList* o)
{
   for(;;)
   {
      HttpSession* s;
      AuthenticatedUser* au;
      DoubleLink* dl = DoubleList_firstNode(&o->list);
      if( ! dl )
         break;
      au = AuthenticatedUser_dlink2Node(dl);
      DoubleLink_unlink(dl); 
      s = AuthenticatedUser_getSession(au);
      HttpSession_terminate(s);
   }
   au1200intclknames(o);
   baFree(o);
}




static void
idmapvector(AuthUserList* o)
{
   baAssert(o->listLen > 0);
   o->listLen--;
   AuthUserList_termIfEmpty(o);
}




int
AuthUserList_createOrCheck(AuthInfo* info,
                           UserIntf* userDb,
                           void** ptr,
                           size_t size)
{

   if(info->maxUsers < 1 ||
      !*info->password ||
      HttpResponse_committed(&info->cmd->response))
   {
      return -1;
   }
   if(ptr)
   {
      *ptr = baMalloc(size);
      if( ! *ptr )
      {
         HttpResponse_sendError1(&info->cmd->response, 503); 
         return -1;
      }
   }
   if(info->authUserList) 
   {
      if(info->authUserList->listLen < info->maxUsers)
         return 0; 
      if( ! singleftouiz(info->authUserList, info) )
         return 0; 
      info->maxUsers = - info->authUserList->listLen;
   }
   else 
   {
      info->authUserList = (AuthUserList*)baMalloc(sizeof(AuthUserList));
      if(info->authUserList)
      {
         pciercxcfg031(info->authUserList,userDb,info);
         if(info->username)
            return 0; 
         baFree(info->authUserList);
      }
      HttpResponse_sendError1(&info->cmd->response, 503); 
   }
   if(ptr)
      baFree(*ptr);
   return -1; 
}


