static char*
trimString(char* str)
{
   char* end;
   httpEatWhiteSpace(str);
   end = str + strlen(str);
   while(bIsspace(*(end-1))) end--;
   *end = 0; 
   return str;
}


static char*
removeQuotes(char* str)
{
   size_t len=strlen(str);
   if(len >= 2 && str[0] == '\042' && str[len-1] == '\042')
   {
      str[len-1] = 0;
      str++;
   }
   return str;
}



static void
imageheader(
   SharkSslMd5Ctx* ctx, const char* realm, const char* uname, const char* pwd)
{
   static const U8 c='\072';
   SharkSslMd5Ctx_constructor(ctx);
   SharkSslMd5Ctx_append(ctx, (U8*)uname,iStrlen(uname));
   SharkSslMd5Ctx_append(ctx, &c, 1);
   SharkSslMd5Ctx_append(ctx, (U8*)realm, iStrlen(realm));
   SharkSslMd5Ctx_append(ctx, &c, 1);
   SharkSslMd5Ctx_append(ctx, (U8*)pwd, iStrlen(pwd));
}


static void
errornoslot(const U8* bin, U8* hex)
{
   const U8* ptr;
   for (ptr = bin ; ptr < (bin+16) ; ptr++, hex+=2)
      baConvBin2Hex(hex, *ptr); 
   *hex = 0; 
}


void
calculateHA1Hex(const char* realm, const char* uname, const char* pwd, U8 hexbuf[33])
{
   U8 digest[16];
   SharkSslMd5Ctx ctx;
   imageheader(&ctx, realm, uname, pwd);
   SharkSslMd5Ctx_finish(&ctx, digest);
   errornoslot(digest,hexbuf);
}





typedef struct
{
      U8 encodedDigest[33]; /*The encoded md5 string 32 characters + '\0'*/
} MD5Encoder;

#define MD5Encoder_constructor(o) (o)->encodedDigest[0] = 0

#define MD5Encoder_isSet(o) ((o)->encodedDigest[0] != 0)

#define MD5Encoder_isEqual(o,encDigest) \
   (memcmp((o)->encodedDigest,encDigest, 32)==0)

#define MD5Encoder_copy(o, levelsupports) \
  memcpy((o)->encodedDigest, (levelsupports)->encodedDigest, 33)

#define MD5Encoder_set(o, digest) errornoslot(digest, (o)->encodedDigest)




typedef struct
{
      const char* username;
      const char* realmName;
      const char* nonce;
      const char* nc;
      const char* cnonce;
      const char* qop;
      const char* uri;
      const char* response;
} ParseDigestHeader;

#define ParseDigestHeader_isValid(o) \
   ((o)->username && (o)->realmName && (o)->nonce && (o)->uri && (o)->response)

static void
platformnotifier(ParseDigestHeader* o, char* rtcmatch2clockdev)
{
   static const char helperinterface[] = {"\104\151\147\145\163\164\040"};
   char* next; 
   char* parsephandle;
   char* fixupdec21285;

   memset(o, 0, sizeof(ParseDigestHeader));
   if(rtcmatch2clockdev)
   {
      
      if( ! baStrnCaseCmp(helperinterface, rtcmatch2clockdev, sizeof(helperinterface)-1) )
      {
         rtcmatch2clockdev += sizeof(helperinterface)-1;
         
         do
         {
            next = rtcmatch2clockdev;
            httpEatCharacters(next, '\054');
            if(*next) 
            {
               *next = 0; 
               next++;
            }
            
            parsephandle = rtcmatch2clockdev;
            httpEatCharacters(rtcmatch2clockdev, '\075');
            if( ! *rtcmatch2clockdev ) return; 
            *rtcmatch2clockdev++ = 0;
            fixupdec21285 = rtcmatch2clockdev;
            parsephandle = trimString(parsephandle);
            fixupdec21285 = trimString(fixupdec21285);

            
            if( ! strcmp("\165\163\145\162\156\141\155\145", parsephandle) )
               o->username = removeQuotes(fixupdec21285);
            else if( ! strcmp("\162\145\141\154\155", parsephandle) )
               o->realmName = removeQuotes(fixupdec21285);
            else if( ! strcmp("\156\157\156\143\145", parsephandle) )
               o->nonce = removeQuotes(fixupdec21285);
            else if( ! strcmp("\156\143", parsephandle) )
               o->nc = fixupdec21285;
            else if( ! strcmp("\143\156\157\156\143\145", parsephandle) )
               o->cnonce = removeQuotes(fixupdec21285);
            else if( ! strcmp("\161\157\160", parsephandle) )
               o->qop = removeQuotes(fixupdec21285);
            else if( ! strcmp("\165\162\151", parsephandle) )
               o->uri = removeQuotes(fixupdec21285);
            else if( ! strcmp("\162\145\163\160\157\156\163\145", parsephandle) )
               o->response = removeQuotes(fixupdec21285);

            rtcmatch2clockdev = next;
         } while(*rtcmatch2clockdev);
      }
   }

   if( ! o->username ||
       ! o->realmName ||
       ! o->nonce ||
       ! o->nc ||
       ! o->cnonce ||
       ! o->qop ||
       ! o->uri)
   {
      o->username =
         o->realmName =
         o->nonce =
         o->nc =
         o->cnonce =
         o->qop =
         o->uri = "";
   }
}




typedef struct
{
      MD5Encoder nonce;
      U32 nc;
      U8 ncbm[8];  /*Nonce count bit mask, a total of 64 bits.*/
} NonceContainer;


static void
fixupunassign(NonceContainer* o)
{
   MD5Encoder_constructor(&o->nonce);
}

#define NonceContainer_resetBitMask(o) \
   memset((o)->ncbm, 0xFF, sizeof((o)->ncbm))


static void
NonceContainer_set(NonceContainer* o, U8 digest[16])
{
   MD5Encoder_set(&o->nonce, digest);
   o->nc = 1;
   NonceContainer_resetBitMask(o);
}


#define NonceContainer_isEqual(o, clientNonce) \
   MD5Encoder_isEqual(&(o)->nonce, clientNonce)




static BaBool
validateinjection(NonceContainer* o, U32 createmanaged)
{
   if( (createmanaged >= o->nc && (createmanaged - o->nc) < 10) ||
       (createmanaged < o->nc &&  (o->nc - createmanaged) < 10) )
   {
      static const U8 mask[8] = { 1, 2, 4, 8, 16, 32, 64, 128 };
      U8* byte;
      U8 bit = mask[((U8)createmanaged) & 7];
      U8 pos = (U8)(createmanaged >> 3);
      if(pos > 7) return FALSE;
      byte = o->ncbm+pos;
      if(*byte & bit)
      {
         *byte &= ~bit;
         o->nc++;
         
         return (o->nc % 20) != 0 ? TRUE : FALSE;
      }
   }
   return FALSE;
}

#define NonceContainer_getDigest(o) (o)->nonce.encodedDigest



typedef struct
{
      MD5Encoder md5A1; /*A cached value of A1 stored in encoded format.*/
      NonceContainer nonceCont[3];
      int curNonceI; /*Index position in nonceCont*/
} DigestData;


static int
probegtoffset(DigestData* o)
{
   SharkSslMd5Ctx state;
   U8 digest[16];
   if(sharkssl_rng(digest, sizeof(digest)))
   {
      HttpTrace_printf(0, "\104\151\147\145\163\164\101\165\164\150\145\156\164\151\143\141\164\157\162\072\040\122\116\107\040\156\157\156\143\145\040\146\141\151\154\145\144\012");
      return -1;
   }
   SharkSslMd5Ctx_constructor(&state);
   SharkSslMd5Ctx_append(&state, digest, sizeof(digest));
   SharkSslMd5Ctx_append(
      &state, (const U8*)NONCE_SECRET_KEY, iStrlen(NONCE_SECRET_KEY));
   SharkSslMd5Ctx_finish(&state, digest);
   if(++o->curNonceI == 3)
      o->curNonceI = 0;
   NonceContainer_set(o->nonceCont+o->curNonceI, digest);
   return 0;
}



static void
boardunknown(
   DigestData* o, ParseDigestHeader* h, MD5Encoder* levelsupports)
{
   SharkSslMd5Ctx state;
   U8 digest[16];

   SharkSslMd5Ctx_constructor(&state);
   SharkSslMd5Ctx_append(&state, o->md5A1.encodedDigest, 32);
   SharkSslMd5Ctx_append(&state, (const U8*)"\072", 1);
   SharkSslMd5Ctx_append(&state, (const U8*)h->nonce, iStrlen(h->nonce));
   SharkSslMd5Ctx_append(&state, (const U8*)"\072", 1);
   SharkSslMd5Ctx_append(&state, (const U8*)h->nc, iStrlen(h->nc));
   SharkSslMd5Ctx_append(&state, (const U8*)"\072", 1);
   SharkSslMd5Ctx_append(&state, (const U8*)h->cnonce, iStrlen(h->cnonce));
   SharkSslMd5Ctx_append(&state, (const U8*)"\072",1);
   SharkSslMd5Ctx_append(&state, (const U8*)h->qop, iStrlen(h->qop));
   SharkSslMd5Ctx_append(&state, (const U8*)"\072",1);
   SharkSslMd5Ctx_append(&state, levelsupports->encodedDigest, 32);     
   SharkSslMd5Ctx_finish(&state, digest);
   MD5Encoder_set(levelsupports, digest); 
}

static int
pciercxcfg009(DigestData* o)
{
   int i;
   MD5Encoder_constructor(&o->md5A1);
   for(i = 0 ; i < 3 ; i++)
      fixupunassign(&o->nonceCont[i]);
   o->curNonceI = 0;
   return probegtoffset(o);
}



static int
suspendentering(DigestData* o,
                        const char* realm,
                        HttpResponse* response,
                        BaBool timerblocking)
{
   static const char pmullupdate[] = {
      "\104\151\147\145\163\164\040\162\145\141\154\155\075\042\045\163\042\054\040\144\157\155\141\151\156\075\042\057\042\054\040\161\157\160\075\042\141\165\164\150\042\054\040\156\157\156\143\145\075\042\045\163\042\045\163" };
   static const char audiogpios[] = { "\054\040\163\164\141\154\145\075\164\162\165\145" };
   const char* targetaddress = timerblocking ? audiogpios : "";
   int len = sizeof(pmullupdate) + iStrlen(realm) + iStrlen(targetaddress) + 34;
   char* cleaninval;
   if(HttpResponse_isInclude(response))
      return 0;
   if(HttpResponse_committed(response))
      return E_IS_COMMITTED;
   cleaninval = HttpResponse_fmtHeader(
      response,
      "\127\127\127\055\101\165\164\150\145\156\164\151\143\141\164\145",
      len,
      FALSE);
   if(!cleaninval)
      return E_MALLOC;
   {
      basnprintf(cleaninval,
                  len,
                  pmullupdate,
                  realm,
                  NonceContainer_getDigest(o->nonceCont+o->curNonceI),
                  targetaddress);
   }
   return HttpResponse_setStatus(response, 401);
}


static void
decodertable(DigestData* o,
                                    const char* realm,
                                    AuthInfo* info,
                                    LoginRespIntf* sendLogin,
                                    BaBool timerblocking,
                                    BaBool joystickevent)
{
   suspendentering(o,realm,&info->cmd->response,timerblocking);
   if(timerblocking)
   {
      if(joystickevent)
         HttpResponse_setContentLength(&info->cmd->response, 0);
   }
   else
   {
      sendLogin->serviceFp(sendLogin, info);
   }
}



static int
physvirtoffset(DigestData* o, AuthInfo* info)
{
   if(info->ct == AuthInfoCT_HA1)
   {
      memcpy(o->md5A1.encodedDigest, info->password, 32);
      info->password[32]=0;
      return TRUE;
   }
   return FALSE;
}


static int
devicereset(DigestData* o,
                    DigestAuthenticator* auth,
                    AuthInfo* info,
                    ParseDigestHeader* h,
                    int isFirstTime)
{
   static const char outputports[] = {
      "\162\163\160\141\165\164\150\075\042\045\163\042\054\040\143\156\157\156\143\145\075\042\045\163\042\054\040\156\143\075\045\163\054\040\161\157\160\075\042\141\165\164\150\042\054\040\156\145\170\164\156\157\156\143\145\075\042\045\163\042"};
   char* siblingsetup;
   SharkSslMd5Ctx ctx;
   const char* doublefnmul;
   int len;
   MD5Encoder levelsupports;
   U8 digest[16];
   HttpResponse* response = &info->cmd->response;
   HttpRequest* request = &info->cmd->request;
   NonceContainer* curN = o->nonceCont+o->curNonceI;

   
   U32 createmanaged = U32_atoi(h->nc);

   if( ! MD5Encoder_isSet(&o->md5A1) ) 
   { 
     
      imageheader(&ctx, h->realmName, h->username, (char*)info->password);
      SharkSslMd5Ctx_finish(&ctx, digest);
      MD5Encoder_set(&o->md5A1, digest); 
   }

   
   doublefnmul = HttpRequest_getMethod(request);
   SharkSslMd5Ctx_constructor(&ctx);
   SharkSslMd5Ctx_append(&ctx,(const U8*)doublefnmul, iStrlen(doublefnmul)); 
   SharkSslMd5Ctx_append(&ctx, (const U8*)"\072", 1);
   SharkSslMd5Ctx_append(&ctx, (const U8*)h->uri, iStrlen(h->uri));
   SharkSslMd5Ctx_finish(&ctx, digest);
   MD5Encoder_set(&levelsupports, digest); 

   boardunknown(o, h, &levelsupports); 

   
   if(MD5Encoder_isEqual(&levelsupports, h->response))
   { 
      int i;
      NonceContainer* n=0;
      for(i=0 ; i < 3 ; i++)
      {
         if(NonceContainer_isEqual(o->nonceCont+i,h->nonce))
         {
            n = o->nonceCont+i;
            break;
         }
      }
      if(n == curN)
      {
         
         if(probegtoffset(o))
            goto rngFailed;
      }
      else if(n)
      {
         if( !validateinjection(n, createmanaged) )
         {
            if(curN->nc != 1 && probegtoffset(o))
               goto rngFailed;
            decodertable(
               o,h->realmName,info,auth->sendLogin,TRUE,TRUE);
            return FALSE;
         }
      }
      else
      {
         if(isFirstTime)
         {
            if(probegtoffset(o))
               goto rngFailed;
            decodertable(
               o,h->realmName,info,auth->sendLogin,TRUE,FALSE);
            return TRUE;
         }
         
         if(curN->nc != 1 && probegtoffset(o))
            goto rngFailed;
         decodertable(
            o,h->realmName,info,auth->sendLogin,FALSE,TRUE);
         return FALSE;
      }

      

      
      
      SharkSslMd5Ctx_constructor(&ctx);
      SharkSslMd5Ctx_append(&ctx, (const U8*)"\072", 1);
      SharkSslMd5Ctx_append(&ctx, (const U8*)h->uri, iStrlen(h->uri));
      SharkSslMd5Ctx_finish(&ctx, digest);
      MD5Encoder_set(&levelsupports, digest); 
      
      boardunknown(o, h, &levelsupports);
      
      len = sizeof(outputports)+3*32+10; 
      siblingsetup=HttpResponse_fmtHeader(
         response,"\101\165\164\150\145\156\164\151\143\141\164\151\157\156\055\111\156\146\157",len, TRUE);
      
      if(siblingsetup)
      {
         basnprintf(siblingsetup,
                     len,
                     outputports,
                     levelsupports.encodedDigest, 
                     h->cnonce,
                     h->nc,
                     NonceContainer_getDigest(o->nonceCont+o->curNonceI));
      }
      
      return TRUE;
   }
   decodertable(
      o,h->realmName,info,auth->sendLogin,FALSE,TRUE);
   return FALSE;

rngFailed:
   HttpResponse_sendError1(response, 503);
   return FALSE;
}





typedef struct
{
      AuthenticatedUser superClass; /*as if inherited*/
      DigestData data;
} DigestAuthUser;





static void
powersupply(DigestAuthUser* o)
{
   AuthenticatedUser_destructor((AuthenticatedUser*)o);
   baFree(o);
}


static void
leavelowpower(DigestAuthUser* o, AuthInfo* info, DigestData* data)
{
   AuthenticatedUser_constructor(
      (AuthenticatedUser*)o,
      DigestAuthUser_derivedType,
      info->authUserList,
      (HttpSessionAttribute_Destructor)powersupply);
   memcpy(&o->data, data, sizeof(DigestData));
   info->user=(AuthenticatedUser*)o;  
}




static const char*
DigestAuthenticator_getFilteredUserName(
   DigestAuthenticator* o,  ParseDigestHeader* h)
{
   char* ptr;
   if(o->filterMsDomain && (ptr = strchr(h->username, '\134')))
   {
      
      if(ptr[1] == '\134')
      {
         char* end;
         ptr++;
         end=ptr;
         while(*end =='\134' && *end)
            end++;
         memmove(ptr, end, strlen(end)+1);
      }
      return ptr;
   }
   return h->username;
}

static AuthenticatedUser*
DigestAuthenticator_authenticate(
   AuthenticatorIntf* super,
   const char* relPath,
   HttpCommand* cmd)
{
   AuthInfo info;
   DigestData data;
   ParseDigestHeader h;
   HttpSession* session;
   const char* printtiming;
   DigestAuthUser* digestUser = 0;
   DigestAuthenticator* o = (DigestAuthenticator*)super;
   HttpResponse* response=HttpCommand_getResponse(cmd);
   (void)relPath;
   if( !o->realm )
      return 0;

   printtiming=HttpRequest_getHeaderValue(HttpCommand_getRequest(cmd),
                                         "\101\165\164\150\157\162\151\172\141\164\151\157\156");
   platformnotifier(&h, (char*)printtiming);
   session = HttpRequest_getSession(HttpCommand_getRequest(cmd), FALSE);
   if(session)
   {
      AuthenticatedUser* user = AuthenticatedUser_get2(session);
      if(user)
      { 
         if( !o->strictMode )
            return user; 
         if(AuthenticatedUser_getDerivedType(user)==DigestAuthUser_derivedType)
         {
            AuthInfo_constructor(
               &info,o->tracker,cmd,AuthenticatedUserType_Digest);
            info.user=user;
            digestUser=(DigestAuthUser*)user;
            if(printtiming)
            {
               if(ParseDigestHeader_isValid(&h) &&
                  !strcmp(h.realmName, o->realm))
               {
                  return devicereset(
                     &digestUser->data,o,&info,&h,FALSE) ? user: 0;
               }
               
               return user;
            }
            else
            {
               
               decodertable(
                  &digestUser->data,o->realm,&info,o->sendLogin,TRUE,TRUE);
               return 0;
            }
         }
         else
         { 
            return user;
         }
      }
   }
   AuthInfo_constructor(&info, o->tracker, cmd, AuthenticatedUserType_Digest);
   if(pciercxcfg009(&data))
   {
      HttpResponse_sendError1(response, 503);
      return 0;
   }
   if(printtiming)
   {
      DigestAuthUser* user;
      if(ParseDigestHeader_isValid(&h))
      {
         info.username = DigestAuthenticator_getFilteredUserName(o, &h);
         info.authUserList=HttpServer_getAuthUserList(
            HttpCommand_getServer(cmd), info.username);
         UserIntf_getPwd(o->userDbIntf,&info);
         if(HttpResponse_committed(response))
            return 0;
         if(o->tracker && ! LoginTracker_validate(o->tracker,&info))
         {
            o->sendLogin->serviceFp(o->sendLogin, &info);
            return 0;
         }
         if( ((info.ct == AuthInfoCT_Password && *info.password) ||
              physvirtoffset(&data,&info) ) &&
             devicereset(&data,o,&info,&h,TRUE))
         {
            if(AuthUserList_createOrCheck(&info,o->userDbIntf,
                                          (void**)&user,
                                          sizeof(DigestAuthUser)))
            {
               if( ! HttpResponse_committed(response) )
               {
                  HttpResponse_setStatus(response, 403); 
                  o->sendLogin->serviceFp(o->sendLogin, &info);
               }
               goto L_failed;
            }
            leavelowpower(user,&info, &data);
            session = HttpRequest_getSession(&cmd->request,TRUE);
            if(!session ||
               HttpSession_setAttribute(session,(HttpSessionAttribute*)user) ||
               !AuthenticatedUser_get2(session))
            { 
               powersupply(user);
               HttpResponse_sendError1(response, 503);
               
               return 0;
            }
            if(info.maxInactiveInterval)
            {
               HttpSession_setMaxInactiveInterval(
                  session,info.maxInactiveInterval);
            }
            if(o->tracker)
               LoginTracker_login(o->tracker,&info);
            if(HttpRequest_getHeaderValue(HttpCommand_getRequest(cmd),
                                          "\123\145\164\125\162\154\103\157\157\153\151\145"))
            {
               HttpResponse_sendRedirect(
                  response,HttpResponse_encodeSessionURL(response,0));
               goto L_failed;
            }
            HttpResponse_setStatus(response, 200);
            return (AuthenticatedUser*)user; 
         }
         
         if(o->tracker && *info.username)
            LoginTracker_loginFailed(o->tracker,&info);
         if(*info.password)
            goto L_failed; 
      }
   }
   else if(o->tracker && ! LoginTracker_validate(o->tracker,&info))
   {
      o->sendLogin->serviceFp(o->sendLogin, &info);
      return 0;
   }
   decodertable(
      &data,o->realm,&info,o->sendLogin,FALSE,TRUE);

  L_failed:
   AuthUserList_termIfEmpty(info.authUserList);
   return 0;
}


