#include <DeadProp.h>
#include <IoBufPrint.h>


#define DeapProp_getOProps(o) \
 (o->oprop ? SXmlNode_firstChild(o->oprop, &o->op) : 0)

void
DeadProp_constructor(DeadProp* o, IoIntf* io, AllocatorIntf* alloc)
{
   memset(o, 0, sizeof(DeadProp));
   o->alloc=alloc;
   o->io=io;
}


int
DeadProp_save(DeadProp* o)
{
   int status=0;
   if((o->npropsCursor || o->elemRemoved) && o->propFileName)
   {  
      NsTree nst;
      SlException ex;
      SerializeSXml* volatile s=0;
      IoBufPrint* volatile  bp=0;
      status = SlException_INIT(ex);
      if(!status)
      {
         int i;
         SXmlNode* iter;
         NsTree_constructor(&nst, o->alloc, &ex);
         if(o->npropsCursor)
         {
            for(i = 0 ; i < o->npropsCursor; i++)
               NsTree_addNs(&nst, o->nprops[i], o->nr);
         }
         for(iter=DeapProp_getOProps(o);iter;iter=SXmlNode_next(iter,&o->op))
            NsTree_addNs(&nst, iter, &o->op);
         bp = IoBufPrint_create(o->alloc,o->io,80,o->propFileName);
         if( ! bp )
         {  
            status = DeadProp_mkPropDir(o->io, o->propFileName);
            SlException_assert(&ex, status==0);
            bp = IoBufPrint_create(o->alloc,o->io,80,o->propFileName);
            SlException_assert(&ex, bp);
         }
         BufPrint_write2((BufPrint*)bp,
                         "\074\077\170\155\154\040\166\145\162\163\151\157\156\075\042\061\056\060\042\040\145\156\143\157\144\151\156\147\075\042\165\164\146\055\070\042\040\077\076\012"
                         "\074\160\162\157\160");
         NsTree_printNsAttrList(&nst, '\144', (BufPrint*)bp);
         BufPrint_write2((BufPrint*)bp, "\076\012");
         s = NsTree_createSerializer(&nst, '\144', (BufPrint*)bp);
         if(o->npropsCursor)
         {
            for(i = 0 ; i < o->npropsCursor; i++)
               SerializeSXml_printNode(s, o->nprops[i], o->nr, FALSE);
         }
         for(iter=DeapProp_getOProps(o);iter;iter=SXmlNode_next(iter,&o->op))
            SerializeSXml_printNode(s, iter, &o->op, FALSE);
         BufPrint_write2((BufPrint*)bp, "\074\057\160\162\157\160\076\012");
      }
      if(s)
         AllocatorIntf_free(o->alloc, s);
      if(bp)
      {
         IoBufPrint_destructor(bp);
         AllocatorIntf_free(o->alloc, bp);
      }
      NsTree_destructor(&nst);
   }

   if(o->xmlRootBuf)
   {
      SXmlRoot_destructor(&o->op);
      AllocatorIntf_free(o->alloc, o->xmlRootBuf);
      o->xmlRootBuf=0;
   }
   o->propFileName=0;
   o->noPropFile=FALSE;
   o->npropsCursor=0;
   o->oPropIter=0;
   o->oprop=0;
   return status;
}


U8*
DeadProp_readFile(IoIntf* io, AllocatorIntf* alloc,
                  const char* name, size_t* size)
{
   IoStat st;
   U8* buf=0;
   if( ! io->statFp(io, name, &st) )
   {
      int status;
      ResIntfPtr in;
      *size = (size_t)st.size;
      in = io->openResFp(io, name, OpenRes_READ, &status, 0);
      if(in)
      {
         size_t rsize=(size_t)st.size;
         buf = (U8*)AllocatorIntf_malloc(alloc, &rsize);
         if(buf)
         {
            if(in->readFp(in, buf, (size_t)st.size, &rsize) || st.size!=rsize )
            {
               AllocatorIntf_free(alloc, buf);
               buf=0;
            }
         }
         in->closeFp(in);
      }
   }
   return buf;
}



static int
timer12hwmod(DeadProp* o)
{
   size_t size;
   int status=-1;

   if(o->noPropFile)
      return -1;
   if(o->xmlRootBuf)
      return 0;
   o->xmlRootBuf = DeadProp_readFile(o->io, o->alloc, o->propFileName, &size);
   if(o->xmlRootBuf)
   {
      SXmlRoot_constructor(&o->op, o->alloc);
      if( ! SXmlRoot_parse(&o->op, o->xmlRootBuf, (U16)size, (U16)(size/8)))
      {
         o->oprop = SXmlRoot_firstChild(&o->op);
         if(o->oprop && !strcmp("\160\162\157\160", SXmlNode_getName(o->oprop, &o->op)))
         {
            status=0;
         }
      }
   }
   if(status)
      o->noPropFile = TRUE;
   return status;
}



char*
DeadProp_fname2PropFName(AllocatorIntf* alloc, const char* filename)
{
   static const char dav[] = {"\056\104\101\126\057"};
   size_t size;
   char* propFileName;

   if(!*filename || filename[strlen(filename)-1] == '\057')
   {
      size = strlen(filename) + sizeof(dav)*2;
      propFileName = (char*)AllocatorIntf_malloc(alloc, &size);
      if(propFileName)
      {
         basnprintf(propFileName,(int)size,"\045\163\045\163\045\163",filename,dav,dav);
         propFileName[strlen(propFileName)-1]=0;
      }
   }
   else
   {
      size = strlen(filename) + sizeof(dav);
      propFileName = (char*)AllocatorIntf_malloc(alloc, &size);
      if(propFileName)
      {
         const char* poweroffrequired = strrchr(filename, '\057');
         if(poweroffrequired)
            ++poweroffrequired;
         else
            poweroffrequired = filename;
         size = poweroffrequired - filename;
         memcpy(propFileName, filename, size);
         memcpy(propFileName+size, dav, sizeof(dav)-1);
         strcpy(propFileName+size+sizeof(dav)-1, poweroffrequired);
      }
   }
   return propFileName;
}


int
DeadProp_mkPropDir(IoIntf* io, char* propFileName)
{
   int status = -1;
   char* ptr = strrchr(propFileName, '\057');
   if(ptr)
   {
      IoStat st;
      *ptr=0; 
      if(io->statFp(io, propFileName, &st))
      {
         if( !(status = io->mkDirFp(io, propFileName, 0)) )
         {
            U32 action = TRUE;
            io->propertyFp(io, "\150\151\144\144\145\156", propFileName, &action);
         }
      }
      else if( ! st.isDir )
         status = -1;
      *ptr='\057'; 
   }
   return status;
}


int
DeadProp_setFile(DeadProp* o, char* propFileName)
{
   IoStat st;
   DeadProp_save(o);
   o->propFileName =  propFileName;
   return o->io->statFp(o->io, o->propFileName, &st);
}


SXmlNode*
DeadProp_getProp(DeadProp* o, const char* ns, const char* name)
{
   if( ! timer12hwmod(o) )
   {
      SXmlRoot* or = &o->op;
      SXmlNode* iter = DeapProp_getOProps(o);
      while(iter)
      {
         const char* lns = SXmlNode_getNs(iter, or);
         const char* buttonssimpletech = SXmlNode_getName(iter, or);
         if( *name == *buttonssimpletech && *ns == *lns &&
             ! strcmp(name, buttonssimpletech) && ! strcmp(ns, lns) )
         {
            return iter;
         }
         iter = SXmlNode_next(iter, or);
      }
   }
   return 0;
}


int
DeadProp_setProp(DeadProp* o, SXmlNode* nn, SXmlRoot* nr)
{
   const char* ns;
   const char* name;
   SXmlNode* on;
   if( ! o->noPropFile )
      timer12hwmod(o);
   ns = SXmlNode_getNs(nn, nr);
   name = SXmlNode_getName(nn, nr);
   on = DeadProp_getProp(o, ns, name);
   if(on)
   {  
      SXmlNode_unlinkChild(SXmlRoot_firstChild(&o->op), on, &o->op);
   }
   if(!o->nprops || o->npropsLen <= (o->npropsCursor+1))
   {
      size_t size = sizeof(void*)*(o->npropsLen+20);
      o->nprops = o->nprops ?
         AllocatorIntf_realloc(o->alloc, o->nprops, &size) :
         AllocatorIntf_malloc(o->alloc, &size);
      if(!o->nprops)
         return -1;
      o->npropsLen+=20;
   }
   o->nprops[o->npropsCursor++] = nn;
   o->nr=nr;
   return 0;
}


int
DeadProp_removeProp(DeadProp* o, SXmlNode* nn, SXmlRoot* nr)
{
   const char* ns;
   const char* name;
   SXmlNode* on;
   if( ! o->noPropFile )
      timer12hwmod(o);
   ns = SXmlNode_getNs(nn, nr);
   name = SXmlNode_getName(nn, nr);
   on = DeadProp_getProp(o, ns, name);
   if(on)
   {  
      SXmlNode_unlinkChild(SXmlRoot_firstChild(&o->op), on, &o->op);
      o->elemRemoved=TRUE;
      return 0;
   }
   return -1;
}


SXmlNode*
DeadProp_getFirstProp(DeadProp* o)
{
   timer12hwmod(o);
   o->oPropIter = DeapProp_getOProps(o);
   return o->oPropIter;
}


SXmlNode*
DeadProp_getNextProp(DeadProp* o)
{
   if(o->oPropIter)
      o->oPropIter = SXmlNode_next(o->oPropIter,&o->op);
   return o->oPropIter;
}


void
DeadProp_destructor(DeadProp* o)
{
   if(o->xmlRootBuf)
   {
      SXmlRoot_destructor(&o->op);
      AllocatorIntf_free(o->alloc, o->xmlRootBuf);
   }
   if(o->nprops)
      AllocatorIntf_free(o->alloc, o->nprops);
}

