   d1_ = (q)[1] ^ SHARKSSL_AES_CT_ROTATE((q)[1], n2, mask2);                    \
   d2_ = (q)[2] ^ SHARKSSL_AES_CT_ROTATE((q)[2], n2, mask2);                    \
   d3_ = (q)[3] ^ SHARKSSL_AES_CT_ROTATE((q)[3], n2, mask2);                    \
   d4_ = (q)[4] ^ SHARKSSL_AES_CT_ROTATE((q)[4], n2, mask2);                    \
   d5_ = (q)[5] ^ SHARKSSL_AES_CT_ROTATE((q)[5], n2, mask2);                    \
   d6_ = (q)[6] ^ SHARKSSL_AES_CT_ROTATE((q)[6], n2, mask2);                    \
   d7_ = (q)[7] ^ SHARKSSL_AES_CT_ROTATE((q)[7], n2, mask2);                    \
   (q)[0] ^= d6_;                                                               \
   (q)[1] ^= d6_ ^ d7_;                                                         \
