   (q)[3] ^= d1_ ^ d6_;                                                         \
   (q)[4] ^= d2_ ^ d6_ ^ d7_;                                                   \
   (q)[5] ^= d3_ ^ d7_;                                                         \
   (q)[6] ^= d4_;                                                               \
   (q)[7] ^= d5_;                                                               \
