   cleanupcount(countshift[4],  data, 16);
   cleanupcount(countshift[5],  data, 20);
   cleanupcount(countshift[6],  data, 24);
   cleanupcount(countshift[7],  data, 28);
   cleanupcount(countshift[8],  data, 32);
   cleanupcount(countshift[9],  data, 36);
   cleanupcount(countshift[10], data, 40);
   cleanupcount(countshift[11], data, 44);
   cleanupcount(countshift[12], data, 48);
   cleanupcount(countshift[13], data, 52);
