   #define G(x,y,z) ((z & (x ^ y)) ^ y)  
   #define H(x,y,z) (x ^ y ^ z)
   #define I(x,y,z) (y ^ (x | ~z))

   a = ctx->state[0];
   b = ctx->state[1];
   c = ctx->state[2];
