      lower = ((((U32)c - '\141') | ('\172' - (U32)c)) >> 31) ^ 1;
      bootmemalloc = ((((U32)c - '\060') | ('\071' - (U32)c)) >> 31) ^ 1;
      plus = (((U32)c ^ '\053') - 1) >> 31;
      slash = (((U32)c ^ '\057') - 1) >> 31;
      
