static int
virtiobegin(RecIoIter* o, const char* from, const char* to)
{
   DirIntfPtr dir;
   const char* str=0;
   int status=0;
   o->recCounter++;
   dir = o->io->openDirFp(o->io, from, &status, &str);
   if(dir)
   {
      while ( ! dir->readFp(dir) && !status )
      {
         str = dir->getNameFp(dir);
         if(str[0]== '\056'&& (!str[1] || (str[1]=='\056' && !str[2])))
            continue;
         if( ! (status = dir->statFp(dir, &o->st)) )
         {
            size_t len = strlen(from) + strlen(str) + 2;
            char* f2 = AllocatorIntf_malloc(o->alloc, &len);
            if(f2)
            {
               char* t2=0;
               basnprintf(f2, (int)len, "\045\163\057\045\163", from, str);
               if(to)
               {
                  len = strlen(to) + strlen(str) + 2;
                  t2 = AllocatorIntf_malloc(o->alloc, &len);
                  if(!t2)
                  {
                     status = o->onErrFp(o, from, IOINTF_MEM, 0);
                     goto L_release;
                  }
                  basnprintf(t2, (int)len, "\045\163\057\045\163", to, str);
               }
               if(o->st.isDir)
               {
                  o->st.size=0;
                  if( ! (status = o->onResponseFp(o, f2, t2, &o->st)) )
                  {
                     if( ! (status = virtiobegin(o, f2, t2)) )
                     {
                        o->st.isDir=TRUE;
                        o->st.size=~((BaFileSize)0);
                        status = o->onResponseFp(o, f2, 0, &o->st);
                     }
                  }
                  else if(status == 403)
                     status=0; 
               }
               else
               {
                  if(o->st.size == 0)
                     o->st.size = 1;
                  status = o->onResponseFp(o, f2, t2, &o->st);
               }
              L_release:
               AllocatorIntf_free(o->alloc, f2);
               if(t2)
                  AllocatorIntf_free(o->alloc, t2);
            }
            else
               status = o->onErrFp(o, from, IOINTF_MEM, 0);
         }
         else
            status = o->onErrFp(o, from, status, 0);
      }
      o->io->closeDirFp(o->io, &dir);
   }
   else
      status = o->onErrFp(o, from, status, str);
   o->recCounter--;
   return status;
}


int
RecIoIter_doResource(RecIoIter* o, const char* from, const char* to)
{
   int status;
   if(o->io->statFp(o->io, from, &o->st))
      return o->onErrFp(o, from, IOINTF_NOTFOUND, 0);
   if(o->st.isDir)
   {
      char* f=0;
      char* t=0;

      if(from[strlen(from)-1] == '\057')
      {
         if( !(f = baStrdup2(o->alloc, from)) )
         {
            return o->onErrFp(o, from, IOINTF_MEM, 0);
         }
         f[strlen(f)-1]=0;
         from = f;
      }
      if(to)
      {
         if(to[strlen(to)-1] == '\057')
         {
            if( !(t = baStrdup2(o->alloc, to)) )
            {
               status = o->onErrFp(o, from, IOINTF_MEM, 0);
               goto L_release;
            }
            t[strlen(t)-1]=0;
            to = t;
         }
         if( ! strcmp(from,to) )
            if( (status = o->onErrFp(
                    o, from, IOINTF_EXIST,
                    "\123\157\165\162\143\145\040\141\156\144\040\144\145\163\164\151\156\141\164\151\157\156\040\141\162\145\040\164\150\145\040\163\141\155\145\040\146\151\154\145")) != 0)
            {
               goto L_release;
            }
      }
      o->st.size=0;
      if( ! (status = o->onResponseFp(o, from, to, &o->st)) )
      {
         if( ! (status = virtiobegin(o, from, to)) )
         {
            o->st.isDir=TRUE;
            o->st.size=~((BaFileSize)0);
            status = o->onResponseFp(o, from, 0, &o->st);
         }
      }
     L_release:
      if(f)
         AllocatorIntf_free(o->alloc, f);
      if(t)
         AllocatorIntf_free(o->alloc, t);
   }
   else
   {
      if(o->st.size == 0)
         o->st.size = 1;
      status = o->onResponseFp(o, from, to, &o->st);
   }
   return status;
}

