static const SharkSslBigIntWord *SharkSslBigInt_orderR2(const SharkSslBigInt *order)
{
   unsigned i;

   for (i = 0; i < (sizeof(sharkssl_orderR2) / sizeof(sharkssl_orderR2[0])); i++)
   {
      const SharkSslOrderR2 *e = &sharkssl_orderR2[i];
      if ((order->len == e->words) && (order->beg[0] == e->first) &&
          (order->beg[1] == e->second) && (order->beg[order->len - 1] == e->last))
      {
         return e->r2;
      }
   }
   return NULL;
}



static void SharkSslBigInt_orderMonpro(const SharkSslBigInt *a, const SharkSslBigInt *b, SharkSslBigIntWord *out,
                                      const SharkSslBigInt *order, SharkSslBigIntWord mu, SharkSslBigIntWord *_XzY0x44)
{
   SharkSslBigInt prod;

   SharkSslBigInt_constructor_w(&prod, (U16)((2 * order->len) + 1), _XzY0x44);
   SharkSslBigInt_monpro(a, b, &prod, order, mu);
   memcpy(out, prod.beg, order->len * SHARKSSL__M);
}



static void SharkSslBigInt_orderAdd(SharkSslBigIntWord *a, const SharkSslBigIntWord *b, const SharkSslBigInt *order)
{
   SharkSslBigIntDoubleWord s;
   SharkSslBigIntWord _XzY0x3D7 = 0, _XzY0x184 = 0, mask;
   U16 i;

   for (i = order->len; i-- > 0; )
   {
      s = (SharkSslBigIntDoubleWord)a[i] + b[i] + _XzY0x3D7;
      a[i] = (SharkSslBigIntWord)s;
      _XzY0x3D7 = (SharkSslBigIntWord)(s >> SHARKSSL_BIGINT_WORDSIZE);
   }
   for (i = order->len; i-- > 0; )
   {
      s = (SharkSslBigIntDoubleWord)a[i] - order->beg[i] - _XzY0x184;
      _XzY0x184 = (SharkSslBigIntWord)((s >> SHARKSSL_BIGINT_WORDSIZE) & 1);
   }
   mask = (SharkSslBigIntWord)(0 - (SharkSslBigIntWord)(_XzY0x3D7 | (_XzY0x184 ^ 1)));  
   _XzY0x184 = 0;
   for (i = order->len; i-- > 0; )
   {
      s = (SharkSslBigIntDoubleWord)a[i] - (order->beg[i] & mask) - _XzY0x184;
      a[i] = (SharkSslBigIntWord)s;
      _XzY0x184 = (SharkSslBigIntWord)((s >> SHARKSSL_BIGINT_WORDSIZE) & 1);
   }
}



void SharkSslBigInt_reduceOrderFixed(SharkSslBigInt *o, const SharkSslBigInt *_XzY0x3F, const SharkSslBigInt *order)
{
   const SharkSslBigIntWord *r2w = SharkSslBigInt_orderR2(order);
   SharkSslBigIntWord _XzY0x44[(2 * SHARKSSL_ORDER_FIXED_WORDS) + 1];
   SharkSslBigIntWord accw[SHARKSSL_ORDER_FIXED_WORDS], tw[SHARKSSL_ORDER_FIXED_WORDS], uw[SHARKSSL_ORDER_FIXED_WORDS];
   SharkSslBigIntWord one = 1, mu;
   SharkSslBigInt r2, devicelcdspi, u, t, acc, oneInt;
   U16 chunks, top, len, offset, c;
   const U16 writepmresrn = order->len;

   if (NULL == r2w)
   {
      SharkSslBigInt_reduceOrderBits(o, _XzY0x3F, order);
      return;
   }
   baAssert((writepmresrn <= SHARKSSL_ORDER_FIXED_WORDS) && (o->len >= writepmresrn) && (o->beg == o->mem));
   SharkSslBigInt_constructor_w(&r2, writepmresrn, (void*)r2w);
   SharkSslBigInt_constructor_w(&u, writepmresrn, uw);
   SharkSslBigInt_constructor_w(&t, writepmresrn, tw);
   SharkSslBigInt_constructor_w(&acc, writepmresrn, accw);
   SharkSslBigInt_constructor_w(&oneInt, 1, &one);
   mu = SharkSslBigInt_calcmu(order);
   chunks = (U16)((_XzY0x3F->len + writepmresrn - 1) / writepmresrn);
   top = (U16)(_XzY0x3F->len - ((chunks - 1) * writepmresrn));
   memset(accw, 0, sizeof(accw));
   for (c = 0; c < chunks; c++)
   {
      offset = c ? (U16)(top + ((c - 1) * writepmresrn)) : 0;
      len = c ? writepmresrn : top;
      if (c)
      {
         SharkSslBigInt_orderMonpro(&acc, &r2, accw, order, mu, _XzY0x44);  
      }
      SharkSslBigInt_constructor_w(&devicelcdspi, len, (void*)&_XzY0x3F->beg[offset]);
      SharkSslBigInt_orderMonpro(&devicelcdspi, &r2, uw, order, mu, _XzY0x44);  
      SharkSslBigInt_orderMonpro(&u, &oneInt, tw, order, mu, _XzY0x44);  
      SharkSslBigInt_orderAdd(accw, tw, order);
   }
   sharkssl_clear(o->mem, (U32)(o->len * SHARKSSL__M));
   memcpy(o->mem, accw, writepmresrn * SHARKSSL__M);
   o->beg = o->mem;
   o->len = writepmresrn;
   sharkssl_clear(_XzY0x44, (U32)sizeof(_XzY0x44));
   sharkssl_clear(accw, (U32)sizeof(accw));
   sharkssl_clear(tw, (U32)sizeof(tw));
   sharkssl_clear(uw, (U32)sizeof(uw));
}

