void SharkSslBigInt_moduloOrderFixed(SharkSslBigInt *o, const SharkSslBigInt *order)
{
   SharkSslBigInt_reduceOrderFixed(o, o, order);
}



void SharkSslBigInt_addmodOrderFixed(SharkSslBigInt *o, const SharkSslBigInt *_XzY0x1C0, const SharkSslBigInt *order)
{
   SharkSslBigIntWord sum[SHARKSSL_ORDER_FIXED_WORDS + 1];
   SharkSslBigInt value;
   SharkSslBigIntDoubleWord _XzY0x3D7 = 0;
   U16 i;
   const U16 writepmresrn = order->len;

   baAssert((writepmresrn <= SHARKSSL_ORDER_FIXED_WORDS) && (o->len == writepmresrn) && (_XzY0x1C0->len <= writepmresrn) && (o->beg == o->mem));
   
   for (i = 0; i < writepmresrn; i++)
   {
      _XzY0x3D7 += (SharkSslBigIntDoubleWord)o->beg[writepmresrn - 1 - i] + ((i < _XzY0x1C0->len) ? _XzY0x1C0->beg[_XzY0x1C0->len - 1 - i] : 0);
      sum[writepmresrn - i] = (SharkSslBigIntWord)_XzY0x3D7;
      _XzY0x3D7 >>= SHARKSSL_BIGINT_WORDSIZE;
   }
   sum[0] = (SharkSslBigIntWord)_XzY0x3D7;
   SharkSslBigInt_constructor_w(&value, (U16)(writepmresrn + 1), sum);
   SharkSslBigInt_moduloOrderFixed(&value, order);
   memcpy(o->mem, value.beg, writepmresrn * SHARKSSL__M);
   o->beg = o->mem;
   o->len = writepmresrn;
   sharkssl_clear(sum, (U32)sizeof(sum));
}
