void
JVal_setX(JVal* o, JErr* e, JVType t, void* v)
{
  if(o->type == JVType_Array || o->type == JVType_Object)
  {
    JErr_setTypeErr(e, o->type, t);
    return;
  }
  if(o->type == JVType_String && o->v.s)
  {
    JErr_setError(e,JErrT_MemErr, "\112\126\141\154\072\072\163\145\164\130\040\163\164\162\151\156\147\040\155\165\163\164\040\142\145\040\155\141\156\141\147\145\144");
    return;
  }
  o->type = t;
  o->stringLen=0;
  switch(t)
  {
         case JVType_String:
            o->v.s=(U8*)v;
            o->stringLen=v ? strlen((char*)v) : 0;
            break;
         case JVType_Double:
            o->v.f=*((double*)v);
            break;
         case JVType_Int:
            o->v.d=*((S32*)v);
            break;
         case JVType_Long:
            o->v.l=*((S64*)v);
            break;
         case JVType_Boolean:
            o->v.b = *((BaBool*)v) ? TRUE : FALSE;
            break;
         case JVType_Null:
            break;
         default:
            baAssert(0);

   }
}


int
JVal_unlink(JVal* o, JVal* child)
{
   if( (o->type == JVType_Object || o->type == JVType_Array) &&
       o->v.firstChild )
   {
      JVal* iter;
      if(child == o->v.firstChild)
      {
         o->v.firstChild = child->next;
         child->next=0;
         return 0;
      }
      iter = o->v.firstChild;
      while(iter->next && iter->next != child)
        iter = iter->next;
      if(iter->next)
      {
         iter->next = child->next;
         child->next=0;
         return 0;
      }
   }
   return -1;
}

static int
segmentnumber(JVal* o, JVal* child)
{
   if(child->next)
      return -1;
   child->next=o->v.firstChild;
   o->v.firstChild=child;
   return 0;
}


int
JVal_addMember(JVal* o, JErr* e, const char* memberName,
               JVal* child, AllocatorIntf* dAlloc)
{
   if(JErr_noError(e))
   {
      if(o->type == JVType_Object)
      {
         if( ! child->memberName )
         {
            child->memberName =
               dAlloc ? baStrdup2(dAlloc, memberName) : (char*)memberName;
            if(child->memberName)
               child->memberNameLen=strlen(memberName);
         }
         if(child->memberName)
            return segmentnumber(o, child);
         JErr_setError(e,JErrT_MemErr,0);
      }
      else
         JErr_setTypeErr(e, JVType_Int, o->type);
   }
   return -1;
}


int
JVal_add(JVal* o, JErr* e, JVal* child)
{
   if(JErr_noError(e))
   {
      if(o->type == JVType_Array)
         return segmentnumber(o, child);
      JErr_setTypeErr(e, JVType_Int, o->type);
   }
   return -1;
}


void
JVal_terminate(JVal* o, AllocatorIntf* vAlloc, AllocatorIntf* dAlloc)
{
   while(o)
   {
      JVal* next = o->next;
      if(o->type == JVType_Object || o->type == JVType_Array)
         JVal_terminate(o->v.firstChild, vAlloc, dAlloc);
      else if(o->type == JVType_String)
         AllocatorIntf_free(dAlloc, o->v.s);
      if(o->memberName)
         AllocatorIntf_free(dAlloc, o->memberName);
      AllocatorIntf_free(vAlloc, o);
      o = next;
   }
}





static int
platformcreate(JParserValFact* o)
{
   size_t indexnospec = (o->vStackSize + 32) * sizeof(void*);
   JVal** v = o->vStack ?
      AllocatorIntf_realloc(o->dAlloc, o->vStack, &indexnospec) :
      AllocatorIntf_malloc(o->dAlloc, &indexnospec);
   if(v)
   {
      
      memset(v + o->vStackSize, 0,
             indexnospec - o->vStackSize * sizeof(void*));
      o->vStack = v;
      o->vStackSize=(int)(indexnospec/sizeof(void*));
      return 0;
   }
   o->status=JParserValFactStat_DMemErr;
   return -1;
}


static int
devicecfcon(JParserIntf* super, JParserVal* pv, int recLevel)
{
   JVal* v;
   size_t jValSize = sizeof(JVal);
   JParserValFact* o = (JParserValFact*)super; 
   if(pv->t == JParserT_EndObject || pv->t == JParserT_EndArray)
      return 0; 
   if(++o->nodeCounter >= o->maxNodes)
   {
      o->status=JParserValFactStat_MaxNodes;
      return -1;
   }
   if(recLevel >= o->vStackSize && platformcreate(o))
      return -1;
   if( (v = AllocatorIntf_malloc(o->vAlloc, &jValSize)) == 0 )
   {
      o->status=JParserValFactStat_VMemErr;
      return -1;
   }
   if(pcimtsetup(v, recLevel ? o->vStack[recLevel-1] : 0, pv, o->dAlloc))
   {
      o->status=JParserValFactStat_VMemErr;
      AllocatorIntf_free(o->vAlloc, v);
      return -1;
   }
   if(pv->t == JParserT_BeginObject || pv->t == JParserT_BeginArray)
      o->vStack[recLevel] = v;
   return 0;
}


void
JParserValFact_constructor(
   JParserValFact* o, AllocatorIntf* vAlloc, AllocatorIntf* dAlloc)
{
   memset(o, 0, sizeof(JParserValFact));
   o->vAlloc=vAlloc;
   o->dAlloc=dAlloc;
   JParserIntf_constructor((JParserIntf*)o, devicecfcon);
   o->maxNodes=~(U32)0;
}


JVal*
JParserValFact_manageFirstVal(JParserValFact* o)
{
   if(o->vStack && *o->vStack)
   {
      JVal* v = *o->vStack;
      *o->vStack = 0;
      o->nodeCounter=0;
      return v;
   }
   return 0;
}


void
JParserValFact_termFirstVal(JParserValFact* o)
{
   if(o->vStack)
   {
      if(o->vStack)
      {
         JVal_terminate(*o->vStack, o->vAlloc, o->dAlloc);
         *o->vStack=0;
         o->nodeCounter=0;
      }
      AllocatorIntf_free(o->dAlloc, o->vStack);
      o->vStack=0;
      o->vStackSize=0;
   }
}


void
JParserValFact_destructor(JParserValFact* o)
{
   JParserValFact_termFirstVal(o);
}





void
JValFact_constructor(JValFact* o, AllocatorIntf* vAlloc, AllocatorIntf* dAlloc)
{
   memset(o, 0, sizeof(JValFact));
   o->vAlloc=vAlloc;
   o->dAlloc=dAlloc;
}


JVal*
JValFact_mkVal(JValFact* o, JVType t, const void* uv)
{
   size_t size=sizeof(JVal);
   JVal* v = (JVal*)AllocatorIntf_malloc(o->vAlloc,&size);
   if(v)
   {
      memset(v,0,sizeof(JVal));
      v->type = t;
      switch(t)
      {
         case JVType_String:
            v->v.s=(U8*)baStrdup2(o->dAlloc, (const char*)uv);
            if(!v->v.s)
               t = JVType_InvalidType;
            else
               v->stringLen=strlen((const char*)uv);
            break;
         case JVType_Double:
            v->v.f=*((double*)uv);
            break;
         case JVType_Int:
            v->v.d=*((S32*)uv);
            break;
         case JVType_Long:
            v->v.l=*((S64*)uv);
            break;
         case JVType_Boolean:
            v->v.b = *((BaBool*)uv) ? TRUE : FALSE;
            break;
         case JVType_Null:
         case JVType_Object:
         case JVType_Array:
            break;
         default:
            baAssert(0);
            t = JVType_InvalidType;
      }
      if(t != JVType_InvalidType)
         return v;
      AllocatorIntf_free(o->vAlloc, v);
   }
   return 0;
}


