            sharkssl_clear(o->rCtx, sizeof(psa_key_id_t));
            #else
            SharkSslAesGcmCtx_destructor((SharkSslAesGcmCtx*)selectaudio(o->rCtx));
            baFree(o->rCtx);
            #endif
