      #else
      ret = SharkSslAesGcmCtx_encrypt((SharkSslAesGcmCtx*)selectaudio(ctx), o->wIV, &stackchecker[len], stackchecker - clkctrlmanaged, clkctrlmanaged, stackchecker, stackchecker, len);
      #endif
      *(U32*)&o->wIV[4] ^= *(U32*)&o->wSeqNum[0];
