int SharkSslECCurve_multiply_NB(SharkSslECCurve *o,
                                SharkSslBigInt *k,
                                SharkSslECPoint *result)
{
   #if (SHARKSSL_ECC_USE_NIST || SHARKSSL_ECC_USE_BRAINPOOL)
   SharkSslBigIntWord scalar[SHARKSSL_ORDER_FIXED_WORDS];
   SharkSslBigInt r;
   SharkSslBigIntWord any;
   volatile SharkSslBigIntWord mask;
   int ret = 1;
   U16 i;
   #endif

   baAssert((result->x.len == o->prime.len) && (result->y.len == o->prime.len));
   #if (SHARKSSL_ECC_USE_NIST || SHARKSSL_ECC_USE_BRAINPOOL)
   if (o->order.len != 0)
   {
      SharkSslBigInt_constructor_w(&r, o->order.len, scalar);
      SharkSslBigInt_reduceOrderFixed(&r, k, &o->order);
      any = 0;
      for (i = 0; i < r.len; i++)
      {
         any |= r.beg[i];
      }
      any = (any | (SharkSslBigIntWord)(0 - any)) >> (SHARKSSL_BIGINT_WORDSIZE - 1);
      r.beg[r.len - 1] |= (any ^ 1);
      ret = _XzY0x3CE(o, &r, result);
      ret <<= 1;  
      if (0 == ret)
      {
         mask = (SharkSslBigIntWord)(0 - any);
         for (i = 0; i < o->prime.len; i++)
         {
            result->x.beg[i] &= mask;
            result->y.beg[i] &= mask;
         }
         ret = (int)(any ^ 1);
      }
      sharkssl_clear(scalar, (U32)sizeof(scalar));
      return ret;
   }
   #endif
   return (_XzY0x3CE(o, k, result) << 1);
}


