static int
_XzY0x3D5(const void* pc)
{
#if SHARKSSL_PSA_CONSUMER
   (void)pc;
   return sharkssl_entropy();
#else
   int status = 0;
   const void* stack = &status;
   U32 clock = baGetMsClock();
   BaTime now = baGetUnixTime();
   U8 input[sizeof(pc) + sizeof(stack) + sizeof(clock) + sizeof(now) + 1];
   U8 seed[2 * SHARKSSL_SHA256_HASH_LEN];
   U8* next = input;
   memcpy(next, &pc, sizeof(pc));
   next += sizeof(pc);
   memcpy(next, &stack, sizeof(stack));
   next += sizeof(stack);
   memcpy(next, &clock, sizeof(clock));
   next += sizeof(clock);
   memcpy(next, &now, sizeof(now));
   next += sizeof(now);
   *next = 0;
   status = sharkssl_sha256(input, sizeof(input), seed);
   if(!status)
   {
      *next = 1;
      status = sharkssl_sha256(input, sizeof(input),
                              seed + SHARKSSL_SHA256_HASH_LEN);
      if(!status)
         status = sharkssl_entropyEx(seed, 48);
   }
   sharkssl_clear(input, sizeof(input));
   sharkssl_clear(seed, sizeof(seed));
   return status;
#endif
}


