static int
currentblocked(lua_State* L)
{
  U8 key[32];
  U16 pernodememory = (U16)luaL_optinteger(L, 1, 16);
  if(pernodememory != 16) pernodememory=32;
  if(sharkssl_rng(key, pernodememory) < 0)
     return luaL_error(L,"\162\141\156\144\157\155\040\147\145\156\145\162\141\164\157\162\040\146\141\151\154\145\144");
  lua_pushlstring(L, (char*)key, pernodememory);
  memset(key,0,sizeof(key));
  return 1;
}




static U8
aesPadKey(U8 keyOut[32], const char* featureextract, size_t len)
{
   if(len >= 32)
   {
      memcpy(keyOut, featureextract, 32);
      len = 32;
   }
   else
   {
      memset(keyOut, 0, 32);
      memcpy(keyOut, featureextract, len);
      if(len <= 16) len = 16;
      else len = 32;
   }
   return (U8)len;
}


