static void*
aesFreeString(void* ud, void* ptr, size_t osize, size_t nsize)
{
   (void)ud;
   (void)osize;
   baAssert(nsize == 0);
   (void)nsize;
   baFree(ptr);
   return 0;
}


static int
exceptionhandler(lua_State* L)
{
   size_t keyInLen,dataInLen,captureresource;
   U8* data;
   const char* featureextract = luaL_checklstring(L,1,&keyInLen);
   const char* pcie1controller = luaL_checklstring(L,2,&dataInLen);
   if(dataInLen > (size_t)UINT_MAX-28)
      return cpufreqconfig(L);
   captureresource=dataInLen+28; 
   if(captureresource > (size_t)(INT_MAX/4)*3)
      return cpufreqconfig(L);
   data = (U8*)baLMalloc(L,captureresource);
   if(data)
   {
      SharkSslAesGcmCtx aesCtx;
      BufPrint buf;
      size_t len=(captureresource/3)*4 + (captureresource%3 ? captureresource%3+1 : 0);
      char* output;
      int status;
      U8 key[32];
      U8 keyLen;
      if(sharkssl_rng(data,12) < 0)
      {
         baFree(data);
         return luaL_error(L,"\162\141\156\144\157\155\040\147\145\156\145\162\141\164\157\162\040\146\141\151\154\145\144");
      }
      memcpy(data+12,pcie1controller,dataInLen);
      keyLen = aesPadKey(key, featureextract,keyInLen);
      SharkSslAesGcmCtx_constructor(&aesCtx,key,keyLen);
      SharkSslAesGcmCtx_encrypt(
         &aesCtx,data,data+12+dataInLen,0,0,data+12,data+12,(U32)dataInLen);
      SharkSslAesGcmCtx_destructor(&aesCtx);
      memset(key,0,sizeof(key));
      output=(char*)baLMalloc(L,len+1);
      if(!output)
      {
         baFree(data);
         return restoreextended(L);
      }
      BufPrint_constructor2(&buf,output,(int)len,0,0);
      status=BufPrint_b64urlEncode(&buf,data,(S32)captureresource,FALSE);
      
      baFree(data);
      if(status)
      {
         baFree(output);
         return restoreextended(L);
      }
      output[len]=0;
      lua_pushexternalstring(L,output,len,aesFreeString,0);
      lua_gc(L,LUA_GCSTEP,(size_t)0);
      return 1;
   }
   return restoreextended(L);
}

static int
_XzY0x280(lua_State* L)
{
   lua_pushlstring(L, lua_touserdata(L,1), (size_t)lua_tointeger(L,2));
   return 1;
}

static int
switchrequest(lua_State* L)
{
   int retVal=0, status=0;
   size_t keyInLen;
   size_t l;
   U32 rc;
   U8* b;
   const char* featureextract = luaL_checklstring(L,1,&keyInLen);
   const char* pcie1controller = luaL_checklstring(L,2,&l);
   if(memchr(pcie1controller,0,l))
      return luaL_argerror(L,2,"\145\155\142\145\144\144\145\144\040\116\125\114\040\151\163\040\156\157\164\040\166\141\154\151\144\040\102\141\163\145\066\064");
   if(l > INT_MAX)
      return cpufreqconfig(L);
   l -= l/4;
   b = (U8*)baLMalloc(L,l ? l : 1);
   if(b)
   {
      BaBool overflow;
      rc = baB64Decode(b,(int)l,pcie1controller,&overflow);
      if(overflow)
      {
         baFree(b);
         return luaL_error(L,"\102\141\163\145\066\064\040\157\165\164\160\165\164\040\157\166\145\162\146\154\157\167");
      }
      if(rc >= 28)
      {
          int err;
          U32 dataLen=rc-28;
          SharkSslAesGcmCtx aesCtx;
          U8 key[32];
          U8 keyLen;
          keyLen = aesPadKey(key, featureextract, keyInLen);
          SharkSslAesGcmCtx_constructor(&aesCtx,key,keyLen);
          err=SharkSslAesGcmCtx_decrypt(
             &aesCtx,b,b+12+dataLen,0,0,b+12,b+12,dataLen);
          SharkSslAesGcmCtx_destructor(&aesCtx);
          memset(key,0,sizeof(key));
          if(!err)
          {
             lua_pushcfunction(L,_XzY0x280);
             lua_pushlightuserdata(L,b+12);
             lua_pushinteger(L,dataLen);
             status=lua_pcall(L,2,1,0);
             retVal=1;
          }
          if(dataLen)
             memset(b+12,0,dataLen);
      }
      baFree(b);
   }
   else
      return restoreextended(L);
   if(status)
      return lua_error(L);
   return retVal;
}

static int
updatecurrent(lua_State* L)
{
   lua_Integer l=0,u=LUA_MAXINTEGER;
   lua_Unsigned rnd,range,threshold;
   int regulatorstate=64;
   switch(lua_gettop(L))
   {  
      case 0: 
         break;
      case 1:  
         u = luaL_checkinteger(L, 1);
         if(u == 0)
            u = LUA_MAXINTEGER;
         else
            luaL_argcheck(L, 1 <= u, 1, "\151\156\164\145\162\166\141\154\040\151\163\040\145\155\160\164\171");
         break;
      case 2:  
         l = luaL_checkinteger(L, 1);
         u = luaL_checkinteger(L, 2);
         luaL_argcheck(L, l <= u, 2, "\151\156\164\145\162\166\141\154\040\151\163\040\145\155\160\164\171");
         break;
      default: return luaL_error(L, "\167\162\157\156\147\040\156\165\155\142\145\162\040\157\146\040\141\162\147\165\155\145\156\164\163");
   }
   
   range = (lua_Unsigned)u - (lua_Unsigned)l + 1;
   threshold = range ? ((lua_Unsigned)0 - range) % range : 0;
   do
   {
      if(!regulatorstate-- || sharkssl_rng((U8*)&rnd, sizeof(rnd)) < 0)
         return luaL_error(L,"\162\141\156\144\157\155\040\147\145\156\145\162\141\164\157\162\040\146\141\151\154\145\144");
   } while(rnd < threshold); 
   if(range)
      rnd %= range;
   rnd += (lua_Unsigned)l;
   
   lua_pushinteger(L, rnd <= (lua_Unsigned)LUA_MAXINTEGER ?
                   (lua_Integer)rnd : -(lua_Integer)(~rnd) - 1);
   return 1;
}

static int
systabentry(lua_State* L)
{
   U32 func5fixup;
   U64 restoreguest;
   int size = (int)luaL_checkinteger(L,1);
   if(size <= 4)
   {
      if(sharkssl_rng((U8*)&func5fixup, sizeof(U32)) < 0)
         return luaL_error(L,"\162\141\156\144\157\155\040\147\145\156\145\162\141\164\157\162\040\146\141\151\154\145\144");
   }
   else
   {
      if(sharkssl_rng((U8*)&restoreguest, sizeof(U64)) < 0)
         return luaL_error(L,"\162\141\156\144\157\155\040\147\145\156\145\162\141\164\157\162\040\146\141\151\154\145\144");
   }
   switch(size)
   {
      case 1:
         lua_pushinteger(L, (lua_Unsigned)(func5fixup & 0xFF)); break;
      case 2:
         lua_pushinteger(L, (lua_Unsigned)(func5fixup & 0xFFFF)); break;
      case 3:
         lua_pushinteger(L, (lua_Unsigned)(func5fixup & 0xFFFFFF)); break;
      case 4:
         lua_pushinteger(L, (lua_Unsigned)func5fixup); break;
      case 5:
         lua_pushinteger(L, (lua_Unsigned)(restoreguest & 0xFFFFFFFFFFULL)); break;
      case 6:
         lua_pushinteger(L, (lua_Unsigned)(restoreguest & 0xFFFFFFFFFFFFULL)); break;
      case 7:
         lua_pushinteger(L, (lua_Unsigned)(restoreguest & 0xFFFFFFFFFFFFFFULL)); break;
      case 8:
         lua_pushinteger(L, (lua_Unsigned)restoreguest); break;
      default:
         lua_pushinteger(L,0);
   }
   return 1;
}

static int
secondaryalive(lua_State* L)
{
   luaL_Buffer lb;
   lua_Integer len = luaL_checkinteger(L,1);
   U16 size,disableunprepare;
   U8* buf;
   luaL_argcheck(L, len >= 1 && len <= 0xFFFF, 1, "\163\151\172\145\040\157\165\164\040\157\146\040\162\141\156\147\145");
   size = (U16)len;
   buf = (U8*)luaL_buffinitsize(L, &lb, size+3);
   disableunprepare = size & ~0x3u;
   if(disableunprepare && sharkssl_rng(buf, disableunprepare) < 0)
      return luaL_error(L,"\162\141\156\144\157\155\040\147\145\156\145\162\141\164\157\162\040\146\141\151\154\145\144");
   size = size & 0x3u;
   if(size)
   {
      if(sharkssl_rng(buf+disableunprepare, 4) < 0)
         return luaL_error(L,"\162\141\156\144\157\155\040\147\145\156\145\162\141\164\157\162\040\146\141\151\154\145\144");
   }
   luaL_pushresultsize(&lb, disableunprepare+size);
   return 1;
}


static int
caviumnotifier(lua_State* L)
{
#if SHARKSSL_PSA_CONSUMER
   lua_pushnil(L);
   lua_pushliteral(L, "\142\141\056\162\156\144\163\145\145\144\040\151\163\040\156\157\164\040\163\165\160\160\157\162\164\145\144\040\151\156\040\120\123\101\040\142\165\151\154\144\163");
   return 2;
#else
   int status;
   if(lua_type(L, 1) == LUA_TNUMBER)
   {
      U32 sha512store = (U32)lua_tointeger(L, 1);
      U8 input[4];
      U8 seed[SHARKSSL_SHA256_HASH_LEN];
      unsigned int i;
      
      for(i = 0; i < sizeof(input); ++i)
         input[i] = (U8)(sha512store >> (8 * i));
      status = sharkssl_sha256(input, sizeof(input), seed);
      if(!status)
         status = sharkssl_entropyEx(seed, sizeof(seed));
      sharkssl_clear(input, sizeof(input));
      sharkssl_clear(seed, sizeof(seed));
   }
   else
   {
      size_t len;
      const U8* seed;
      luaL_checktype(L, 1, LUA_TSTRING);
      seed = (const U8*)lua_tolstring(L, 1, &len);
      luaL_argcheck(L, len >= 32 && len <= 65535, 1,
                    "\163\145\145\144\040\142\165\146\146\145\162\040\155\165\163\164\040\143\157\156\164\141\151\156\040\063\062\040\164\150\162\157\165\147\150\040\066\065\065\063\065\040\142\171\164\145\163");
      status = sharkssl_entropyEx(seed, (U16)len);
   }
   if(status)
   {
      lua_pushnil(L);
      lua_pushliteral(L, "\122\116\107\040\162\145\163\145\145\144\040\146\141\151\154\145\144");
      return 2;
   }
   lua_pushboolean(L, TRUE);
   return 1;
#endif
}

