static int
async1pdata(lua_State *L, ResIntf* f, size_t n)
{
   size_t buttonsbuffalo;  
   size_t nr;  
   int status;
   luaL_Buffer b;
   luaL_buffinit(L, &b);
   buttonsbuffalo = LUAL_BUFFERSIZE;  
   do {
      char *p = luaL_prepbuffer(&b);
      if (buttonsbuffalo > n) buttonsbuffalo = n;  
      nr = 0;
      status = f->readFp(f, p,  buttonsbuffalo, &nr);
      luaL_addsize(&b, nr);
      n -= nr;  
   } while (status == 0 && n > 0 && nr == buttonsbuffalo); 
   luaL_pushresult(&b);  
   return status == 0 || status == IOINTF_EOF ? 0 : status;
}


static int
uart1resources(lua_State *L)
{
   ResIntf* f = bres_check(L);
   int nargs = lua_gettop(L) - 1;
   int status=-1;
   int contextoffset=2;
   int n;
   if(nargs == 0)
   {  
      status = async1pdata(L, f, LUAL_BUFFERSIZE);
      n=contextoffset+1;
   }
   else
   {  
      luaL_checkstack(L, nargs+LUA_MINSTACK, "\164\157\157\040\155\141\156\171\040\141\162\147\165\155\145\156\164\163");
      for(n = contextoffset; nargs-- ; n++)
      {
         if(lua_type(L, n) == LUA_TNUMBER)
         {
            size_t l = (size_t)lua_tointeger(L, n);
            status = async1pdata(L, f, l);
         }
         else
         {
            const char *p = luaL_checkstring(L, n);
            if (*p == '\052') p++;  
            if('\141' != *p)
               return luaL_argerror(L, n, "\151\156\166\141\154\151\144\040\146\157\162\155\141\164");
            status = async1pdata(L,f,~((size_t)0)); 
         }
         if(status)
            break;
      }
   }
   if(status)
      return balua_pushstatus(L,status);
   if(lua_rawlen(L, -1) == 0)
   {
      lua_pop(L,1);
      n--;
   }
   return n - contextoffset;
}








