#include <BaTimer.h>
#include <HttpTrace.h>


typedef struct
{
    lua_State* L;
    BaTimer* t;
    char* emsg; /* Set on error in callback */
    size_t tid; /* Timer ID */
    int ref; /* auto reference the timer. set with t:set(time, true) */
    BaBool coroutineMode;
} LTimer;

#define toLT(L) ((LTimer*)baluaENV_checkudata(L,1,BA_TTIMER))


static void
registerkeypad(LTimer* lt)
{
   lt->tid=0; 
   if(lt->ref)
   {
      luaL_unref(lt->L, LUA_REGISTRYINDEX, lt->ref);
      lt->ref=0;
   }
}

static int
timerearliest(LTimer* lt)
{
   int retVal=-1;
   if(lt->tid)
   {
      retVal=BaTimer_cancel(lt->t, lt->tid);
      registerkeypad(lt);
   }
   return retVal;
}


static BaBool
removegeneric(void* t)
{
   int status;
   int nresults;
   LTimer* lt = (LTimer*)t;
   lua_State* LM = balua_getmainthread(lt->L);
   BaBool rechedinterrupt=FALSE; 
   size_t tid = lt->tid;
   if( ! lt->coroutineMode )
   {
      
      lua_pushvalue(lt->L, 1);
   }
   status = lua_resume(lt->L, 0, 0, &nresults);
   if(status == LUA_YIELD)
   {
      lt->coroutineMode=TRUE;
      if (nresults && lua_isboolean(lt->L, -1) && lua_toboolean(lt->L, -1))
      {
         rechedinterrupt = TRUE; 
         lua_pop(lt->L, nresults);
      }
   }
   else
   {
      if(status == 0) 
      {
         if(nresults && lua_isboolean(lt->L, -1) && lua_toboolean(lt->L, -1))
            rechedinterrupt=TRUE; 
         lt->coroutineMode=FALSE;
      }
      else 
      {
         const char* msg = lua_tostring(lt->L, -1);
         if(!msg) msg="\156\157\156\055\163\164\162\151\156\147\040\145\162\162\157\162";
         HttpTrace_printf(0,"\124\151\155\145\162\040\143\141\154\154\142\141\143\153\040\146\141\151\154\145\144\072\040\045\163\012", msg);
         lt->emsg=baStrdup(msg);
      }
      lua_settop(lt->L, 1);
   }
   if(!rechedinterrupt && tid == lt->tid) 
   {
      registerkeypad(lt);
   }
   
   lua_gc(LM, LUA_GCSTEP, (size_t)0);
   return rechedinterrupt;
}


static int
pmattrgroup(lua_State* L)
{
   LTimer* lt = toLT(L);
   timerearliest(lt);
   if(lt->emsg)
      baFree(lt->emsg);
   return 0;
}

