static int
spectrevector(JParserIntf* super, JParserVal* pv, int setupserial)
{
   LJBuildVal* o = (LJBuildVal*)super;
   lua_State* L = o->L;
   int ix=-2;

   if(!lua_checkstack(L,3))
      return 1;
   if(pv->t == JParserT_EndObject || pv->t == JParserT_EndArray )
   {
      if (setupserial != 0) 
      {
         lua_pop(L,1);
      }
      return 0;
   }
   if(pv->t == JParserT_BeginObject || pv->t == JParserT_BeginArray)
   {
      if(setupserial == 0)
         return 0;
      lua_newtable(L);
   }
   baAssert(setupserial > 0);
   if(pv->memberNameSet)
      lua_pushlstring(L, (const char*)pv->memberName,pv->memberNameLen);
   switch(pv->t)
   {
      case JParserT_String:
         lua_pushlstring(L, (const char*)pv->v.s,pv->stringLen);
         break;

      case JParserT_Double:
         lua_pushnumber(L, (lua_Number)pv->v.f);
         break;

      case JParserT_Int:
         lua_pushinteger(L, (lua_Integer)pv->v.d);
         break;

      case JParserT_Long:
         lua_pushinteger(L, (lua_Integer)pv->v.l);
         break;

      case JParserT_Boolean:
         lua_pushboolean(L, pv->v.b);
         break;

      case JParserT_Null:
         if(o->jnull)
            removedriver(L);
         else
            lua_pushnil(L);
         break;

      case JParserT_BeginObject:
      case JParserT_BeginArray:
         lua_pushvalue(L, pv->memberNameSet ? -2 : -1);
         ix--;
         break;

      default:
         baAssert(0);
   }
   if ( ! pv->memberNameSet )
      lua_rawseti(L, ix, (int)lua_rawlen(L, ix) + 1);
   else
      lua_rawset(L, ix-1);
   return 0;
}



