static LJP*
pushJSONParserAndInit(lua_State* L, int ix)
{
   LJP* ljp;
   JParserStackNode* ptr;
   int stackLen;
   int nameLen;
   int jnull;
   if(lua_isboolean(L, ix))
   {
      jnull = lua_toboolean(L, ix);
      ix++;
   }
   else
      jnull=TRUE;
   stackLen = (int)luaL_optinteger(L, ix, 16);
   nameLen = (int)luaL_optinteger(L, ix+1, 255);
   if(stackLen < JPARSER_STACK_LEN) stackLen = JPARSER_STACK_LEN;
   stackLen -= JPARSER_STACK_LEN;
   if(nameLen < 127) nameLen = 127;
   ljp = (LJP*)lua_newuserdata(
      L, sizeof(LJP) + stackLen * sizeof(JParserStackNode) + nameLen);
   JParserIntf_constructor((JParserIntf*)(&ljp->bv), spectrevector);
   ljp->bv.L=L;
   ljp->busy=FALSE;
   LJsonAllocator_constructor(&ljp->alloc, L);
   ljp->bv.jnull=jnull;
   ptr = (JParserStackNode*)(ljp+1); 
   ptr += stackLen; 
   JParser_constructor(&ljp->p, (JParserIntf*)&ljp->bv,
                       (char*)ptr,nameLen,&ljp->alloc.super,stackLen);
   return ljp;
}




