static JVal*
lParseJsonDataString(lua_State* L, int suspenddefault, JParserValFact* vf,
                     LJsonAllocator* alloc)
{
   JParser p;
   DynBuffer dbuf;
   int exceptiontables;
   size_t bufSize;
   const char* buf=0;
   int status=0;
   JVal* val=0;
   LJsonAllocator_constructor(alloc, L);
   if(LUA_TTABLE == lua_type(L,suspenddefault))
   {
      DynBuffer_constructor(&dbuf, 512, 2048, &alloc->super, 0);
      exceptiontables=TRUE;
      lua_newtable(L); 
      status=ljsonlibTabEncode(L, (BufPrint*)&dbuf, lua_gettop(L), suspenddefault);
      if(DynBuffer_getECode(&dbuf))
      {
         DynBuffer_destructor(&dbuf);
         lua_pushnil(L);
         lua_pushliteral(L,"\155\141\154\154\157\143");
         return 0;
      }
      if(status == 1)
      {
         status=0;
         buf=DynBuffer_getBuf(&dbuf);
         bufSize=DynBuffer_getBufSize(&dbuf);
	  }
      else
         status = -1;
   }
   else
   {
      buf = luaL_checklstring(L, suspenddefault, &bufSize);
      exceptiontables=FALSE;
   }
   if( ! status )
   {
      char* nbuf = baLMalloc(L, 1024);
      if(nbuf)
      {
         JParserValFact_constructor(vf, &alloc->super, &alloc->super);
         JParser_constructor(
            &p, (JParserIntf*)vf, nbuf, 1024, &alloc->super,0);
         status=JParser_parse(&p, (const U8*)buf, (U32)bufSize);
         JParser_destructor(&p);
         if(status > 0) 
         {
            val=JParserValFact_getFirstVal(vf);
         }
         else
         {
            JParserValFact_destructor(vf);
            val=0;
            lua_pushnil(L);
            lua_pushliteral(L,"\120\141\162\163\145\040\145\162\162\157\162");
         }
         baFree(nbuf);
      }
      else
      {
         if(exceptiontables)
            DynBuffer_destructor(&dbuf);
         lua_pushnil(L);
         lua_pushliteral(L,"\155\141\154\154\157\143");
         return 0;
      }
   }
   if(exceptiontables==TRUE)
   {
      DynBuffer_destructor(&dbuf);
   }
   return val;
}


