static int
searchhighest(lua_State* L)
{
   size_t chunkSize;
   const void* data;
   int status=0;
   HttpAsynchResp* resp = toAresp(L);
   if(lua_isnil(L, 2))
   {
      data=0;
      chunkSize=0;
   }
   else
      data = luaL_checklstring(L, 2, &chunkSize);
   if(resp->responseState == RESPONSESTATE_IDLE)
   {
      int pktSize = (int)luaL_checkinteger(L, 3);
      luaL_argcheck(L, pktSize >= 0 && (size_t)pktSize >= chunkSize, 3,
                    "\120\141\143\153\145\164\040\163\151\172\145\040\155\165\163\164\040\142\145\040\076\075\040\143\150\165\156\153\040\163\151\172\145");
      status = HttpAsynchResp_sendData(resp, data, pktSize, (int)chunkSize);
   }
   else if(resp->responseState == RESPONSESTATE_BODYSENT)
      status = HttpAsynchResp_sendNextChunk(resp,data, (int)chunkSize);
   else
      return uart3resources(L);
   lua_pushboolean(L, status ? FALSE : TRUE);
   return 1;
}

static int
configtable(lua_State* L)
{
   HttpAsynchResp* resp = toAresp(L);
   int pktSize = (int)luaL_checkinteger(L, 2);
   if(resp->responseState != RESPONSESTATE_IDLE)
      return uart3resources(L);
   lua_pushboolean(L,HttpAsynchResp_sendData(resp,0,pktSize,0)? FALSE : TRUE);
   return 1;
}



static int
disablepciint(lua_State* L)
{
   int i;
   HttpAsynchResp* resp = toAresp(L);
   BufPrint* out = HttpAsynchResp_getWriter(resp);
   if(!out)
   {
      if(HttpAsynchResp_isValid(resp))
         return uart3resources(L);
      return balua_pushstatus(L, E_SOCKET_WRITE_FAILED);
   }
   for(i=2; i <= lua_gettop(L) ; i++)
   {
      size_t chunkSize;
      const void* data = luaL_checklstring(L, i, &chunkSize);
      if(BufPrint_write(out, data, (int)chunkSize) < 0)
      {
         lua_pushboolean(L, FALSE);
         return 1;
      }
   }
   lua_pushboolean(L, TRUE);
   return 1;
}

