static int
mmgpioresource(BufPrint* super, int sizeRequired)
{
   Xrsp* x =(Xrsp*)super;
   if(x->type != 2)
      return -1;
   x->strm.next_in = (Bytef*)super->buf;
   x->strm.avail_in = super->cursor;
   super->cursor=0;
   while(x->strm.avail_in)
   {
      int ret;
      if( ! x->strm.avail_out )
         if( ! xrsp_mknode(x) )
            goto L_error;
      ret = deflate(&x->strm, Z_NO_FLUSH);
      baAssert(ret != Z_STREAM_ERROR);  
      if(ret != Z_OK)
      {
        L_error:
         deflateEnd(&x->strm);
         x->type = 0;
         return -1;
      }
   }
   if(sizeRequired < 0) 
   {
      consolesetup(x, TRUE, 0);
      
      HttpResponse_setResponseBuf(x->resp, (BufPrint*)x, TRUE);
   }
   return 0;
}

static void
suspendenable(lua_State* L, Xrsp* x)
{
   DoubleLink* d;
   while( (d=DoubleList_removeFirst(&x->list)) != 0 )
      baFree(d);
   if(x->last)
   {
      baFree(x->last);
      x->last=0;
   }
   if(x->type == 2)
   {
      deflateEnd(&x->strm);
   }
   x->type=0;
   if(x->funcRef)
   {
      luaL_unref(L, LUA_REGISTRYINDEX, x->funcRef);
      x->funcRef=0;  
   }
   if(x->threadRef)
   {
      luaL_unref(L, LUA_REGISTRYINDEX, x->threadRef);
      x->threadRef=0;  
   }
   x->resp=0;
}


