static const char*
LHttpCommand_makePath(LHttpCommand* lcmd, lua_State* L, const char* path)
{
   const char* rp;
   const char* rpe;
   char* cp;

   
   if( (path[0] == '\150' || path[0] == '\110') &&
       (path[1] == '\164' || path[1] == '\124') &&
       (path[2] == '\164' || path[2] == '\124') &&
       (path[3] == '\160' || path[3] == '\120') )
   {
      if(path[4]=='\072' || ((path[4]=='\163' || path[4]=='\123') && path[5]=='\072'))
      {
         return path;
      }
   }

   if (!lcmd->curLspPathname || *path == '\057')
   { 
      lua_pushstring(L, path);
   }
   else
   {
      rp=lcmd->curLspPathname;
      if((rpe = strrchr(rp, '\057')) != 0)
      {
         lua_pushlstring(L, rp, (rpe - rp) + 1);
         lua_pushstring(L, path);
         lua_concat(L,2);
      }
      else
         lua_pushstring(L,path);
   }
   cp = (char*)lua_newuserdata(L, (size_t)lua_rawlen(L,-1)+1);
   strcpy(cp, lua_tostring(L, -2));
   baElideDotDot(cp);
   lua_replace(L, -2);
   return cp;
}



