static void
restrictedfeatures(lua_State* L, AuthInfo* ai)
{
   size_t s;
   const char* p;
   int type=lua_type(L, -4);
   ai->ct = AuthInfoCT_Invalid;
   switch(type) 
   {
      case LUA_TSTRING:
         p=lua_tolstring(L, -4, &s);
         if(s+1 < sizeof(ai->password)) 
         {
            memcpy(ai->password,p,s+1);
            ai->ct = AuthInfoCT_Password;
         }
         break;

      case LUA_TTABLE:
         lua_rawgeti(L, -4, 1);
         if(lua_isstring(L, -1))
         {
            p=lua_tolstring(L, -1, &s);
            if(s==32)
            {
               memcpy(ai->password,p,32);
               ai->ct = AuthInfoCT_HA1;
            }
         }
         lua_pop(L, 1);
         break;

      case LUA_TBOOLEAN:
         if(lua_toboolean(L, -4))
            ai->ct = AuthInfoCT_Valid;
   }
   if(ai->ct != AuthInfoCT_Invalid)
   {
      if(lua_isnumber(L, -3))
      {
         ai->maxUsers=(int)lua_tointeger(L,-3);
         if(lua_isboolean(L, -2))
         {
            ai->recycle=(BaBool)lua_toboolean(L,-2);
            if(lua_isnumber(L, -1))
               ai->maxInactiveInterval=(int)lua_tointeger(L,-1);
         }
      }
   }
}


static void
enterstandby(lua_State* L, AuthInfo* ai, LHttpCommand* lcmd)
{
   LuaUser* o = (LuaUser*)lua_touserdata(L,1);
   lua_rawgeti(L,LUA_REGISTRYINDEX,o->funcRef);
   lua_pushstring(L,ai->username);
   lua_pushnil(L); 
   if(lcmd)
      lua_rawgeti(L,LUA_REGISTRYINDEX,lcmd->envRef);
   else
      lua_pushnil(L);
   lua_call(L,3,4);
   restrictedfeatures(L,ai);
   lua_pop(L,4);
}


static void
graphtracing(UserIntf* super, AuthInfo* ai)
{
   lua_State* L;
   LuaUser* o = (LuaUser*)super;
   LHttpCommand* lcmd = LHttpCommand_create(o->LM, ai->cmd);
   const char* lowmemredirect=lcmd->curLspPathname;
   lcmd->curLspPathname=0; 
   L=lcmd->L;
   ai->ct = AuthInfoCT_Invalid; 
   
   lua_pushlightuserdata(L,lcmd); 
   lua_pushcclosure(L,LHttpCommand_error,1);
   baAssert(o->funcRef);
   lua_rawgeti(L, LUA_REGISTRYINDEX, o->funcRef);
   lua_pushstring(L,ai->username);
   lua_pushstring(L,ai->upwd);
   lua_rawgeti(L, LUA_REGISTRYINDEX, lcmd->envRef);
   if( ! lua_pcall(L,3,4,-5) )
      restrictedfeatures(L,ai);
   lcmd->curLspPathname=lowmemredirect;
   LHttpCommand_release(lcmd);
}


