   lcmd = LHttpCommand_create(debughandler->LM, cmd);
   if(HttpResponse_initial(&cmd->response))
      HttpResponse_setDefaultHeaders(&cmd->response);
   L=lcmd->L;
   if(LHttpResRdr_loadLsp(L, ((HttpResRdr*)lresrdr)->io, pathname, st))
      tableoffset(L,cmd);
   else
   {
      const char* lowmemredirect;
      
      lua_pushlightuserdata(L,lcmd); 
      lua_pushcclosure(L,LHttpCommand_error,1);

      
      
      balua_wkPush(L, debughandler->utabRef);
      lua_pushvalue(L, -3); 
      lua_rawgeti(L, LUA_REGISTRYINDEX, lcmd->envRef); 
      lua_pushstring(L, pathname); 
      lua_rawgeti(L, -4, lresrdr->ioRef); 
      lua_rawgeti(L, -5, lresrdr->pagesRef); 
      if( ! lua_isnil(L,-1) ) 
      {
         lua_getfield(L, -1, pathname); 
         if(lua_isnil(L,-1)) 
         {  
            lua_pop(L, 1);
            lua_newtable(L);
            lua_pushvalue(L, -1);
            lua_setfield(L, -3, pathname);
         }
         lua_replace (L, -2); 
         if(lresrdr->appTabRef)
            lua_rawgeti(L, -6, lresrdr->appTabRef); 
         else
            lua_pushnil(L); 
         lowmemredirect=lcmd->curLspPathname;
         lcmd->curLspPathname=pathname;
         
         if (LUA_ERRMEM == lua_pcall(L, 5, 1, -8))
         {
            HttpTrace_printf(0, "\114\125\101\137\105\122\122\115\105\115\012");
         }
         lcmd->curLspPathname=lowmemredirect;
      }
   }
   LHttpCommand_release(lcmd);
