static int
notifierregister(lua_State *L)
{
   const char* k;
   const char* v;
   HttpResRdrHeader* h;
   size_t hn,hs;
   LHttpResRdr* o = LHttpResRdr_check(L,1);
   luaL_checktype(L,2,LUA_TTABLE);
   hn=hs=0;
   
   lua_pushnil(L);  
   while(lua_next(L,2) != 0)
   {
      k = lua_tostring(L, -2);
      v = lua_tostring(L, -1);
      if(k && v)
      {
         hn++;
         hs += strlen(k) + strlen(v) + 2;
      }
      lua_pop(L, 1);  
   }
   hn++;
   if((hn*sizeof(HttpResRdrHeader)+hs) < 0xFFFF)
   {
      if(hn == 1)
      {
         HttpResRdr_setHeader((HttpResRdr*)o, 0); 
         lua_pushboolean(L,1);
         return 1;
      }
      h = (HttpResRdrHeader*)baLMalloc(L, hn*sizeof(HttpResRdrHeader)+hs);
      if(h)
      {
         
         char* ptr = (char*)(h+hn);
         hn=0;
         lua_pushnil(L);  
         while(lua_next(L, 2) != 0)
         {
            k = lua_tostring(L, -2);
            v = lua_tostring(L, -1);
            if(k && v)
            {
               
               size_t l = strlen(k)+1;
               memcpy(ptr, k, l);
               h[hn].keyIx = (U16)(ptr - (char*)h);
               ptr+=l;
               
               l = strlen(v)+1;
               memcpy(ptr, v, l);
               h[hn].valIx = (U16)(ptr - (char*)h);
               ptr+=l;
               hn++;
            }
            lua_pop(L, 1);
         }
         h[hn].keyIx = 0;
         h[hn].valIx = 0;
         HttpResRdr_setHeader((HttpResRdr*)o, h);
         lua_pushboolean(L,1);
         return 1;
      }
   }
   lua_pushboolean(L,0);
   return 1;
}




