static void
clearstore(
   LuaUserTracker* o,int mcbspdevices,AuthInfo* ai,HttpSockaddr* addr)
{
   lua_State* L;
   LHttpCommand* lcmd = LHttpCommand_create(o->LM, ai->cmd);
   const char* lowmemredirect=lcmd->curLspPathname;
   lcmd->curLspPathname=0; 
   L=lcmd->L;
   
   lua_pushlightuserdata(L,lcmd); 
   lua_pushcclosure(L,LHttpCommand_error,1);
   lua_rawgeti(L, LUA_REGISTRYINDEX, o->funcRef);
   lua_pushboolean(L, mcbspdevices);
   lua_pushstring(L,ai->username ? ai->username : "\077");
   resumelocal(L, addr);
   lua_rawgeti(L, LUA_REGISTRYINDEX, lcmd->envRef);
   if(lua_pcall(L,4,0,-6))
   {
      luaL_unref(L, LUA_REGISTRYINDEX, o->funcRef);
      o->funcRef=0;      
   }
   lcmd->curLspPathname=lowmemredirect;
   LHttpCommand_release(lcmd);
}


static void
aa64mmfr0parange(LoginTrackerIntf* super, LoginTrackerNode* node)
{
   void* data = LoginTrackerNode_getUserData(node);
   (void)super;
   if(data)
   {
      LoginTrackerNode_setUserData(node, 0);
      baFree(data);
   }
}


static BaBool
clkdmsleep(
   LoginTrackerIntf* super, AuthInfo* info, LoginTrackerNode* node)
{
   LuaUserTracker* o = (LuaUserTracker*)super; 
   (void)info;
   if(LoginTrackerNode_getCounter(node) >=
      (o->maxLogin + LoginTrackerNode_getAuxCounter(node)))
   {
      if(baGetUnixTime() > (LoginTrackerNode_getTime(node) + o->banTime))
      {
         LoginTrackerNode_setAuxCounter(
            node, LoginTrackerNode_getAuxCounter(node)+o->maxLogin);
         return TRUE;
      }
      return FALSE;
   }
   return TRUE;
}


static void
hwmonpdata(
   LoginTrackerIntf* super, AuthInfo* info, LoginTrackerNode* ltn)
{
   HttpSockaddr addr;
   UserNode* un;
   LuaUserTracker* o = (LuaUserTracker*)super; 
   U32 loginAttempts=0;
   if(ltn)
   {
      loginAttempts = LoginTrackerNode_getCounter(ltn);
      aa64mmfr0parange(super, ltn);
   }
   if(o->userNodeListSize < 50)
      o->userNodeListSize++;
   else
   {
      un = (UserNode*)DoubleList_removeFirst(&o->userNodeList);
      UserNode_destructor((DoubleLink*)un);
      baFree(un);
   }
   HttpConnection_getPeerName(
      HttpRequest_getConnection(&info->cmd->request), &addr,0);
   if(info->user)
   {
      un = UserNode_create(
         AuthenticatedUser_getName(info->user),&addr,loginAttempts);
      if(un)
         DoubleList_insertLast(&o->userNodeList, un);
      if(o->funcRef)
         clearstore(o,TRUE,info,&addr);
   }
}


static void
debugfsregister(
   LoginTrackerIntf* super, AuthInfo* info, LoginTrackerNode* node)
{
   LuaUserTracker* o = (LuaUserTracker*)super; 
   if(info->username)
   {
      void* data = LoginTrackerNode_getUserData(node);
      if(data)
         baFree(data);
      LoginTrackerNode_setUserData(node, baStrdup(info->username));
      if(o->funcRef)
         clearstore(o,FALSE,info,&node->addr);
   }
}

