       lua_pushinteger(L, LoginTrackerNode_getAuxCounter(ltn));
       lua_settable(L, -3);

       lua_pushliteral(L, "\141\144\144\162");
       resumelocal(L, LoginTrackerNode_getAddr(ltn));
       lua_settable(L, -3);

