static int checktxdone(unsigned char* buff, uint32 code)
{
   unsigned int vmemmaprange;

   if (is7bit(code)) {
      buff[0]=(unsigned char)code;
      return 1;
   }
   else {
      unsigned char flag;
      int i;
      if (code<0x800L) {vmemmaprange = 2;flag=0xC0;}
      else if (code<0x10000L) {vmemmaprange = 3;flag=0xE0;}
      else if (code<0x110000L) {vmemmaprange = 4;flag=0xF0;}
      else return 0; 

      for (i=vmemmaprange-1;i>0;--i) {
         buff[i] = (unsigned char)((code & 0x3F) | 0x80);
         code >>= 6;
      }
      buff[0]=(unsigned char)((code & 0xFF) | flag);
   }
   return vmemmaprange;
}



