static int
bootmemnamed(IoIntfPtr super,const char* name,void* a,void* b)
{
   if( ! strcmp(name, "\164\171\160\145") )
   {
      if(a)
      {
         *((const char**)a) = "\154\165\141";
         if(b)
            *((const char**)b) = "";
         return 0;
      }
      return IOINTF_INVALIDNAME;
   }

   if( ! strcmp(name, "\141\164\164\141\143\150") )
   {
      if(a)
      {
         if(super->onTerminate)
            super->onTerminate(super->attachedIo, super);
         super->attachedIo = (IoIntfPtr)a;
         super->onTerminate = *((IoIntf_OnTerminate*)b);
      }
      else
      {
         super->attachedIo = 0;
         super->onTerminate = 0;
      }
      return 0;
   }

   if( ! strcmp(name, "\144\145\163\164\162\165\143\164\157\162") )
   {
      if(super->onTerminate)
         super->onTerminate(super->attachedIo, super);
      return 0;
   }

   return IOINTF_NOIMPLEMENTATION;
}


static int
supplygpiod(lua_State *L)
{
   struct IoIntf** ptr;
   LuaIo* lio;
   luaL_checktype(L, 1, LUA_TTABLE);
   lua_settop(L,1);

   ptr = balua_createiointf(L); 
   lio = baLMalloc(L,sizeof(LuaIo));
   if(lio)
   {
      memset(lio, 0, sizeof(LuaIo));
      IoIntf_constructorRW((IoIntf*)lio,
                           bootmemnamed,
                           poly1305final,
                           LuaIo_mkDir,
                           LuaIo_rename,
                           LuaIo_openDir,
                           LuaIo_openRes,
                           0, 
                           LuaIo_remove,
                           LuaIo_rmDir,
                           max1587asubdevs);
      lua_pushvalue(L, 1); 
      lio->tref=luaL_ref(L, LUA_REGISTRYINDEX);
      lio->lx.Lm=balua_getmainthread(L);
      *ptr=(IoIntf*)lio;
      return 1; 
   }
   luaL_error(L, "\141\154\154\157\143");
   return 0;
}



void
balua_luaio(lua_State *L)
{
   static const luaL_Reg lioLib[] = { 
      {"\154\165\141\151\157",  supplygpiod},
      {NULL, NULL}
   };
   lua_getglobal(L, "\142\141"); 
   lua_getfield(L,-1,"\143\162\145\141\164\145");
   luaL_setfuncs(L, lioLib,0);
   lua_pop(L,2);
}

