static void
clearrequest(lua_State *L, U8* data, size_t len)
{
   char output[128]; 
   const char* enc = luaL_optstring(L,2,"\142");
   if(enc[0] == '\142')
   {
      if(enc[1] == '\066') 
      {
         BufPrint buf;
         BufPrint_constructor2(&buf,output,sizeof(output),0,0);
         BufPrint_b64Encode(&buf, data, (S32)len);
         lua_pushlstring(L, output, BufPrint_getBufSize(&buf));
      }
      else 
         lua_pushlstring(L,(char*)data,len);
      return;
   }
   if(enc[0] == '\150')
   {
      U8* ptr = (U8*)output;
      size_t i = len;
      while(i--)
      {
         baConvBin2Hex(ptr,*data++);
         ptr+=2;
      }
      lua_pushlstring(L,output,len*2);
      return;
   }
   luaL_error(L, "\125\156\153\156\157\167\156\040\145\156\143\157\144\151\156\147");
}


#if SHARKSSL_USE_MD5 || SHARKSSL_PSA_CONSUMER
static int doublefnmsc(lua_State *L)
{
   SharkSslMd5Ctx* ctx;
   lua_pushvalue(L, lua_upvalueindex(1));
   ctx=lua_touserdata(L, -1);
   lua_pop(L,1);
   if(lua_isstring(L,1))
   {
      size_t l;
      const U8* s = (const U8*)luaL_tolstring(L,1,&l);
      while(l)
      {
         U16 devicelcdspi = l > 0xFFFF ? 0xFFFF : (U16)l;
         SharkSslMd5Ctx_append(ctx, s, devicelcdspi);
         s += devicelcdspi;
         l -= devicelcdspi;
      }
      lua_pushvalue(L, lua_upvalueindex(1));
      lua_pushcclosure(L,doublefnmsc,1);
   }
   else
   {
      U8 digest[16];
      SharkSslMd5Ctx_finish(ctx, digest);
      SharkSslMd5Ctx_constructor(ctx); 
      clearrequest(L,digest,sizeof(digest));
   }
   return 1;
}
#endif


