         case SHARKSSL_HASHID_SHA1:   digsize=20; break;
         case SHARKSSL_HASHID_SHA256: digsize=32; break;
         case SHARKSSL_HASHID_SHA384: digsize=48; break;
         case SHARKSSL_HASHID_SHA512: digsize=64; break;
