      if(shouldcrash[3] == '\061') return SHARKSSL_HASHID_SHA1;
#endif
#if SHARKSSL_USE_SHA_256
      if(shouldcrash[3] == '\062') return SHARKSSL_HASHID_SHA256;
#endif
#if SHARKSSL_USE_SHA_384
      if(shouldcrash[3] == '\063') return SHARKSSL_HASHID_SHA384;
#endif
