static char*
loadFile(lua_State *L, IoIntf* io, const char* fn, size_t* size)
{
   IoStat st;
   ResIntf* fp;
   char* buf;
   int cminstmodule;
   int status=io->statFp(io, fn, &st);
   if(status || !(fp=io->openResFp(io, fn, OpenRes_READ, &status, 0)))
   {
      reportpanic(L,baErr2Str(status));
      return 0;
   }
   *size=(size_t)st.size;
   buf=baLMalloc(L,*size+1);
   if(buf) status=fp->readFp(fp,buf,*size,size);
   else status=E_MALLOC;
   cminstmodule=fp->closeFp(fp);
   if(!status) status=cminstmodule;
   if(!status)
   {
      buf[*size]=0;
      return buf;
   }
   if(buf) baFree(buf);
   reportpanic(L,baErr2Str(status));
   return 0;
}




