      keyUsage->bits = SHARKSSL_X509_KU_DIGITAL_SIGNATURE;

   if(args > (clearflags+1))
      hashID = mcspi1hwmod(L, luaL_checkstring(L, clearflags+2), clearflags+2);
   else
      hashID = SHARKSSL_HASHID_SHA256;

