static int
LThreadMgr_doDir(HttpCmdThreadPoolIntf* super, HttpCommand* cmd, HttpDir* dir)
{
   LThreadMgr* o = (LThreadMgr*)super;
   if(LThreadMgr_canRun(o))
   {
      HttpCmdJob* dn = (HttpCmdJob*)ThreadJob_create(
         sizeof(HttpCmdJob), LThread_runDoDir);
      if(dn)
      {
         cmd->runningInThread = TRUE;
         dn->server=o->server;
         dn->dir = dir;
         dn->cmd = cmd;
         LThreadMgr_run(o, (ThreadJob*)dn);
         return 0;
      }
   }
   return -1;
}
