static void
LThreadMgr_releaseAllThreads(LThreadMgr* o)
{
   DoubleListEnumerator iter;
   LThread* lt;
   DoubleLink* l;
   DoubleListEnumerator_constructor(&iter, &o->runningThreadList);
   for(l = DoubleListEnumerator_getElement(&iter) ;
       l ;
       l = DoubleListEnumerator_nextElement(&iter))
   {
      LThread_link2Thread(l)->Lt=0; 
   }
   while( 0 != (lt = LThreadMgr_removeFirstIdleThread(o)) )
   {
      lt->Lt=0;  
      DoubleList_insertLast(&o->runningThreadList, &lt->link);
      ThreadSemaphore_signal(&lt->sem);
   }
}



