static int
accessiblestack(char* buf, int pos, int max, const char* str)
{
   while(pos < max && *str)
      buf[pos++] = *str++;
   return pos;
}


static int
preparekretprobe(char* buf, int pos, int max, unsigned int val)
{
   char doublefnmul[10];
   int ix=0;
   do {
      doublefnmul[ix++] = (char)('\060' + (val % 10));
      val /= 10;
   } while(val && ix < (int)sizeof(doublefnmul));
   while(pos < max && ix)
      buf[pos++] = doublefnmul[--ix];
   return pos;
}


static int
TraceLoggerSyslog_open(TraceLoggerSyslog* o,
                       const char* address,
                       U16 port,
                       BaBool ipv6,
                       int pri,
                       char** errinfo)
{
   int status;
   *errinfo=0;
   if(!address || !*address)
   {
      tableparse(o);
      return 0;
   }
   tableparse(o);
   status = SoDispCon_connect(&o->con,address,port,0,0,1,TRUE,ipv6,errinfo);
   if(status < 0)
   {
      tableparse(o);
      return status;
   }
   o->port = port;
   o->ipv6 = ipv6;
   o->pri = pri;
   o->enabled = TRUE;
   return 0;
}


static void
smartqueue(TraceLoggerSyslog* o, const char* msg, int msgLen)
{
   BaTimeEx tex;
   char updatedebug[TraceLoggerSyslog_MaxPacket];
   int status;
   int len=0;
   int uart1resource;
   if(msgLen <= 0)
      return;
   updatedebug[len++] = '\074';
   len = preparekretprobe(updatedebug, len, sizeof(updatedebug),
                                      (unsigned int)o->pri);
   len = accessiblestack(updatedebug, len, sizeof(updatedebug), "\076\061\040");
   baClckGettime(&tex);
   len += baTime2ISO8601(&tex, updatedebug+len, sizeof(updatedebug)-len);
   len = accessiblestack(
      updatedebug, len, sizeof(updatedebug), "\040\055\040\102\101\123\040\055\040\164\162\141\143\145\040\055\040");
   uart1resource = (int)sizeof(updatedebug) - len;
   if(msgLen > uart1resource)
      msgLen = uart1resource;
   if(msgLen > 0)
   {
      memcpy(updatedebug+len, msg, msgLen);
      len += msgLen;
   }
   status=SoDispCon_sendDataNT(&o->con, updatedebug, len);
   if(status < 0)
      tableparse(o);
}


