static void
activationnotifier(Thread* t)
{
   (void)t;
   for(;;)
   {
      TraceBufNode* tbn;
      ThreadSemaphore_wait(&tl->sem);
      tl->threadRunning = TRUE;
      ThreadMutex_set(tl->dispMutex);
      if(tl->exitThread) break;
      while((tbn = (TraceBufNode*)SingleList_removeFirst(&tl->tbnList)) != 0)
      {
#if BA_ENABLE_SYSLOG
         if(tl->syslog.enabled)
            smartqueue(&tl->syslog, tbn->buf+1, tbn->size-1);
#endif
         if(WSS_isValid(&tl->wss))
            WSS_write(&tl->wss, tbn->buf, tbn->size, FALSE);
         tl->tbnListSize -= tbn->size;
         baFree(tbn);
      }
      tl->threadRunning = FALSE;
      ThreadMutex_release(tl->dispMutex);
   }
   tl->threadRunning = FALSE;
   tl->exitThread = 2; 
   ThreadMutex_release(tl->dispMutex);
}


static void
sigreturnsetup(char* buf, int bufLen)
{
   BaBool clearkeypad = WSS_isValid(&tl->wss);
#if BA_ENABLE_SYSLOG
   if(tl->syslog.enabled)
      clearkeypad = TRUE;
#endif
   if(clearkeypad && tl->tbnListSize < 30*1024)
   {
      TraceBufNode* tbn = baMalloc(sizeof(TraceBufNode)+bufLen);
      if(tbn)
      {
         TraceBufNode_constructor(tbn);
         SingleList_insertLast(&tl->tbnList, tbn);
         tbn->buf[0] = TR_data;
         memcpy(tbn->buf + 1, buf, bufLen);
         tbn->size = bufLen + 1;
         tl->tbnListSize += tbn->size;
         if (!tl->threadRunning)
            ThreadSemaphore_signal(&tl->sem);
      }
   }
   if(tl->luaOntraceFuncRef && tl->luaOntraceJobCount < 8)
   {
      TrOntraceThreadJob* job=(TrOntraceThreadJob*)ThreadJob_lcreate(
         sizeof(TrOntraceThreadJob)+ bufLen, flashresources);
      if(job)
      {
         job->len= bufLen;
         memcpy(job->data, buf, bufLen);
         tl->luaOntraceJobCount++;
         LThreadMgr_run(ltMgr, (ThreadJob*)job);
      }
   }
   originalFlushCB(buf, bufLen);
}


