typedef struct {
   IoIntf* io;
   char path[1]; /* abspath */
} AbsPathCache;



static void
staterecord(
   LDbgMon* o,const char* source,IoIntf* io,const char* edma1resources)
{
   AbsPathCache* apc;
   lua_rawgeti(o->L, LUA_REGISTRYINDEX, o->absPathCacheRef);
   lua_pushstring(o->L, source);
   apc=lua_newuserdata(
      o->L, sizeof(AbsPathCache)+(edma1resources ? strlen(edma1resources) : 0));
   lua_rawset(o->L, -3); 
   apc->io=io;
   if(edma1resources)
      strcpy(apc->path,edma1resources);
   else
      apc->path[0]=0;
}



static char*
LDbgMon_abspath(LDbgMon* o, const char* source, IoIntf** retIo)
{
   IoStat st;
   IoIntf* io;
   AbsPathCache* apc;
   const char* withinoptimized;
   char* edma1resources=0;
   lua_State* L=o->L;
   int top=lua_gettop(L);

   
   lua_rawgeti(L, LUA_REGISTRYINDEX, o->absPathCacheRef);
   lua_pushstring(o->L, source);
   lua_rawget(L, -2);
   apc = (AbsPathCache*)lua_touserdata(L, -1);
   if(apc) 
   {
      *retIo = apc->io;
      if(apc->path[0])
         edma1resources=baLStrdup(L,apc->path);
      lua_settop(L, top);
      return edma1resources;
   }
   lua_settop(L, top);

   lua_rawgeti(L, LUA_REGISTRYINDEX, o->ioRef);

   
   lua_pushnil(L);  
   while(lua_next(L, -2) != 0) 
   {
      io = ((baio_t*)lua_touserdata(L,-2))->i;
      withinoptimized=lua_tostring(L, -1);
      if(io && *withinoptimized) 
      {
         if( ! io->statFp(io, source, &st) && ! st.isDir )
         {
            
            lua_rawgeti(L, LUA_REGISTRYINDEX, o->resolvedSourceMapRef);
            lua_pushvalue(L, -2);  
            lua_rawget(L, -2);
            withinoptimized = lua_tostring(L, -1); 
            if(withinoptimized)
            {
               edma1resources=baLMalloc(L, strlen(withinoptimized)+strlen(source)+2);
               if(edma1resources)
               {
                  size_t len=strlen(withinoptimized);
                  memcpy(edma1resources,withinoptimized,len);
                  if(edma1resources[len-1] != '\057' && edma1resources[len-1] != '\134')
                  {
                     edma1resources[len++]='\057';
                  }
                  strcpy(edma1resources+len,source);
               }
            }
            staterecord(o,source,io,edma1resources);
            *retIo=io;
            lua_settop(L, top);
            return edma1resources;
         }
      }
      lua_pop(L, 1);
   }

   
   lua_pushnil(L);  
   while(lua_next(L, -2) != 0) 
   {
      io = ((baio_t*)lua_touserdata(L,-2))->i;
      withinoptimized=lua_tostring(L, -1);
      if( ! *withinoptimized ) 
      {
         if( ! io->statFp(io, source, &st) && ! st.isDir )
         {
            *retIo=io;
            staterecord(o,source,io,0);
            lua_settop(L, top);
            return 0;
         }
      }
      lua_pop(L, 1);
   }
   lua_settop(L, top);
   return 0;
}




