static void
dcachenomsr(LDbgMon* o, int cs89x0resources)
{
   DynBuffer db;
   size_t dummyhwclk;
   int top;
   const char* path;
   lua_State* L=o->L;
   int clockgettime=FALSE;
   BufPrint* out = (BufPrint*)&db;
   if(cs89x0resources)
      DynBuffer_constructor(&db,2048,1024,AllocatorIntf_getDefault(),0);
   top=lua_gettop(L);
   luaL_unref(o->L, LUA_REGISTRYINDEX, o->resolvedSourceMapRef);
   lua_newtable(L);
   lua_pushvalue(L, -1);
   o->resolvedSourceMapRef = luaL_ref(L, LUA_REGISTRYINDEX);
   lua_rawgeti(L, LUA_REGISTRYINDEX, o->ioRef);
   
   if(o->workspaceFolder)
   {
      dummyhwclk=strlen(o->workspaceFolder);
      lua_pushnil(L);  
      while(lua_next(L, -2) != 0) 
      {
         path = lua_tostring(L, -1); 
         if( ! baStrnCaseCmp(o->workspaceFolder, path, dummyhwclk) )
         {
            lua_pushvalue(L, -1);
            lua_rawset(L, top+1); 
            break;
         }
         lua_pop(L,1);
      }
   }
   lua_settop(L,top+2);
   
   if(o->sourceMapRef)
   {
      lua_rawgeti(L, LUA_REGISTRYINDEX, o->sourceMapRef);
      lua_pushnil(L);  
      while(lua_next(L, -2) != 0) 
      {
         int setupiocoherency=FALSE;
         path = lua_tostring(L, -2); 
         dummyhwclk=strlen(path);
         lua_pushvalue(L, top+2); 
         lua_pushnil(L);  
         while(lua_next(L, -2) != 0) 
         {
            const char* hwmodassert = lua_tostring(L, -1);
            
            if( ! baStrnCaseCmp(hwmodassert, path, dummyhwclk) && 
                (strlen(hwmodassert) - dummyhwclk) <= 1)
            {
               lua_pushvalue(L, -4); 
               lua_rawset(L, top+1); 
               setupiocoherency=TRUE;
               lua_pop(L,1);
               break;
            }
            lua_pop(L,1);
         }
         if( ! setupiocoherency )
         {
            if(cs89x0resources)
               BufPrint_printf(out,"\116\157\040\163\157\165\162\143\145\040\155\141\160\160\151\156\147\040\146\157\162\072\040\047\045\163\047\012",path);
            clockgettime=TRUE;
         }
         lua_pop(L,2);
      }
   }
   if(clockgettime && cs89x0resources)
   {
      BufPrint_printf(out,"\103\165\162\162\145\156\164\154\171\040\153\156\157\167\156\040\142\141\163\145\040\160\141\164\150\163\072\012");
      lua_settop(L,top+2);
      lua_pushnil(L);  
      while(lua_next(L, -2) != 0)  
      {
         path = lua_tostring(L, -1);
         if(path[0])
            BufPrint_printf(out,"\011\045\163\012",path);
         lua_pop(L,1);
      }
      systemindex(o, DBG_EV_CONSOLE,DynBuffer_getBuf(&db));
      DynBuffer_destructor(&db);
   }
   lua_settop(L,top);
}



