#define BAFORKPTY "\102\101\106\117\122\113\120\124\131"
#define PTY_NAME_SIZE 64


typedef struct
{
      /* 5 first variables used only in asynch mode */
   SoDispCon super; /* stdin and stdout */
   SoDispCon conStderr;
   lua_State* Lt;
   int ref; /* Reference userdata in LUA_REGISTRYINDEX */
   int pty; /* stdin+stdout terminal. From getpt */
   int pipefd[2];
   int pid; /* From fork */
   int exitCode;
   BaBool hasExitCode;
   BaBool busy;
   BaBool sigint;
} ForkPTY;



static int
alloccipher(lua_State* L,ForkPTY* te)
{
   int ex;
   char* msg=strerror(errno);
   if(waitpid(te->pid, &ex, WNOHANG) <= 0) 
      return lDoErr(L,"\045\163",msg);
   
   lua_pushnil(L);
   lua_pushliteral(L, "\164\145\162\155\151\156\141\164\145\144");
   te->exitCode=ex;
   te->hasExitCode=TRUE;
   return 2;
}


static ForkPTY* 
checkForkPTY(lua_State* L)
{
   ForkPTY* te = (ForkPTY*)luaL_checkudata(L,1,BAFORKPTY);
   
   if(te->busy && L != te->Lt)
      luaL_error(L, "\142\165\163\171");
   if(te->pty < 0)
   {
      cpuidlerestore(L);
      return 0;
   }
   return te;
}


static ForkPTY* 
checkForkPTYOnExit(lua_State* L, int* ret, int terminate)
{
   ForkPTY* te = (ForkPTY*)luaL_checkudata(L,1,BAFORKPTY);
   
   if(te->busy && L != te->Lt)
      luaL_error(L, "\142\165\163\171");
   if(te->pty < 0)
   {
      if(te->hasExitCode)
      {
         if(terminate)
            lua_pushboolean(L, TRUE);
         *ret = terminate + consoledriver(L, te->exitCode);
      }
      else
         *ret = cpuidlerestore(L);
      return 0;
   }
   return te;
}

static void flashprobe(ForkPTY* te)
{
   if(te->Lt) 
   {
      SoDisp* disp = SoDispCon_getDispatcher((SoDispCon*)te);
      if(SoDispCon_recEvActive((SoDispCon*)te))
         SoDisp_deactivateRec(disp,(SoDispCon*)te);
      if(SoDispCon_dispatcherHasCon((SoDispCon*)te))
         SoDisp_removeConnection(disp,(SoDispCon*)te);
      if(SoDispCon_recEvActive(&te->conStderr))
         SoDisp_deactivateRec(disp,&te->conStderr);
      if(SoDispCon_dispatcherHasCon(&te->conStderr))
         SoDisp_removeConnection(disp,&te->conStderr);
   }
}


static void
earlyserial(ForkPTY* te, ThreadMutex* m)
{
   if(te->pty >= 0)
   {
      int pty=te->pty;
      te->pty=-1;
      flashprobe(te);
      te->busy=TRUE;
      ThreadMutex_release(m);
      if(!te->hasExitCode)
      {
         int status;
         do status=waitpid(te->pid, &te->exitCode, WNOHANG);
         while(status < 0 && errno == EINTR);
         if(status == 0 && kill(te->pid, SIGKILL) == 0)
         {
            do status=waitpid(te->pid, &te->exitCode, 0);
            while(status < 0 && errno == EINTR);
         }
         te->hasExitCode = status > 0;
      }
      close(pty);
      if(te->pipefd[0] >= 0)
      {
         close(te->pipefd[0]);
         te->pipefd[0]=-1;
      }
      ThreadMutex_set(m);
      te->busy=FALSE;
      if(te->Lt) 
      {
         luaL_checkstack(te->Lt, 1, 0);
         luaL_unref(te->Lt, LUA_REGISTRYINDEX, te->ref);
      }
   }
}


static int
startuplevel(lua_State* L)
{
   ForkPTY* te = checkForkPTY(L);
   if(!te) return 2;
   if(L == te->Lt) 
   {
      return lua_yield(L, 0); 
   }
   else
   {
      luaL_Buffer lb;
      struct timeval tv;
      fd_set socketSet;
      char* buf;
      int n,isStdErr;
      ThreadMutex* m = getSoDispMutex(L);

      

      if((lua_isboolean(L,2) && lua_toboolean(L, 2)))
      {
         tv.tv_sec = LONG_MAX; 
         tv.tv_usec = 0;
      }
      else if(lua_isnumber(L,2))
      {
         lua_Integer timeout = luaL_checkinteger(L, 2);
         luaL_argcheck(L, timeout >= 0 && timeout <= INT_MAX,
                       2, "\157\165\164\040\157\146\040\162\141\156\147\145");
         n = (int)timeout;
         tv.tv_sec = n / 1000;
         tv.tv_usec = (n % 1000) * 1000; 
      }
      else
      { 
         tv.tv_sec = 0;
         tv.tv_usec = 0;
      }
      int clkctrlproviders = (te->pty > te->pipefd[0] ? te->pty : te->pipefd[0])+1;
      if(clkctrlproviders >= FD_SETSIZE)
      { 
         return lDoErr(L,"\104\145\163\143\040\076\040\106\104\137\123\105\124\123\111\132\105");
      }
      FD_ZERO(&socketSet);
      FD_SET(te->pty, &socketSet);
      FD_SET(te->pipefd[0], &socketSet);
      te->busy=TRUE;
      ThreadMutex_release(m);
      n = select(clkctrlproviders, &socketSet, 0, 0, &tv); 
      ThreadMutex_set(m);
      te->busy=FALSE;
      if(n<0)
         return alloccipher(L,te);
      if(n==0) 
      {
        L_ret:
         lua_pushnil(L);
         return 1;
      }
      if(FD_ISSET(te->pty, &socketSet))
      {
         n = te->pty;
         isStdErr=FALSE;
      }
      else if(FD_ISSET(te->pipefd[0], &socketSet))
      {
         n = te->pipefd[0];
         isStdErr=TRUE;
      }
      else
         goto L_ret;
      luaL_buffinit(L, &lb);
      buf = luaL_prepbuffer(&lb);
      te->busy=TRUE;
      ThreadMutex_release(m);
      n = read(n, buf, LUAL_BUFFERSIZE);
      ThreadMutex_set(m);
      te->busy=FALSE;
      if(n < 0)
         return alloccipher(L,te);
      if(n==0) 
         goto L_ret;
      luaL_addsize(&lb, n);
      luaL_pushresult(&lb);
      lua_pushboolean(L, isStdErr);
      return 2;
   }
}



static void
aa64mmfr1override(ForkPTY* te, int pty)
{
   int status,n,err=FALSE;
   lua_State* L=te->Lt;
   if(lua_status(L) == LUA_YIELD)
   {
      luaL_Buffer lb;
      luaL_buffinit(L, &lb);
      n = read(pty,luaL_prepbuffer(&lb), LUAL_BUFFERSIZE);
      if(n < 0)
      {
         n=alloccipher(L,te);
         err=TRUE;
      }
      else
      {
         luaL_addsize(&lb, n);
         luaL_pushresult(&lb);
         lua_pushboolean(L, te->pipefd[0] == pty);
         n=2;
      }
      status = lua_resume(L, 0, n, &n);
   }
   else
      status = lua_resume(L, 0, 1, &n); 
   if(status == LUA_YIELD)
   {
      lua_settop(L, 0);
      if(err)
         flashprobe(te);
   }
   else
   {
      earlyserial(te, getSoDispMutex(L));
      if(status != 0)
         balua_resumeerr(L,"\146\157\162\153\160\164\171");
   }
}


