typedef struct
{
   DoubleLink super;
   SoDispCon cCon; /* connection to destination server */      
   SoDispCon* sCon; /* Server connection */
   SoDispCon_DispRecEv sConDispEv; /* The overloaded server callback */
   char* domainName;
   int* isTerminatedPtr;
   U16 port;
   BaBool active, responseReady;
} HttpRedirectNode;


#define HttpRedirectNode_sendData(o,data,len)           \
   SoDispCon_sendData(&(o)->cCon, data,len)

static void panelindex(HttpRedirectNode* o, SoDispCon* sCon);
static void unmapgrant(HttpRedirectNode* o);
