static HttpRedirectNode*
HttpRedirectNode_find(SoDispCon* con)
{
   DoubleListEnumerator e;
   HttpRedirectNode* pn;
   DoubleListEnumerator_constructor(&e,&httpRedirectNodeList);
   for(pn = (HttpRedirectNode*)DoubleListEnumerator_getElement(&e) ;
       pn ;
       pn = (HttpRedirectNode*)DoubleListEnumerator_nextElement(&e))
   {
      if(con == pn->sCon)
      {
         return pn;
      }
   }
   return 0;
}


static HttpRedirectNode*
HttpRedirectNode_create(HttpCommand* cmd,DecodeUrl* sramcsubsys)
{
   HttpRedirectNode* pn = HttpRedirectNode_find((SoDispCon*)cmd->con);
   if(pn)
   {
      if(!SoDispCon_isValid(&pn->cCon) || !pn->domainName ||
         pn->port != sramcsubsys->port || strcmp(pn->domainName, sramcsubsys->domainName))
      { 
         if(pn->domainName)
            baFree(pn->domainName);
         pn->domainName=0;
         SoDispCon_closeCon(&pn->cCon);
         goto L_connect;
      }
   }
   if(!pn)
   {
      pn = baMalloc(sizeof(HttpRedirectNode));
      if(pn)
      {
         panelindex(pn,(SoDispCon*)cmd->con);
        L_connect:
         if(smc91xdevice(pn,sramcsubsys,cmd))
         {
            unmapgrant(pn);
            baFree(pn);
            pn = 0;
         }
      }
      else
         HttpResponse_sendError1(&cmd->response,503);
   }
   return pn;
}



static void
panelindex(HttpRedirectNode* o, SoDispCon* sCon)
{
   DoubleLink_constructor((DoubleLink*)o);
   SoDispCon_constructor(&o->cCon,
                                SoDispCon_getDispatcher(sCon),
                                applystate);
   o->sCon = sCon;
   
   o->sConDispEv = sCon->dispRecEv; 
   o->sCon->dispRecEv = l2c310write;
   DoubleList_insertLast(&httpRedirectNodeList,o);
   o->domainName=0;
   o->isTerminatedPtr=0;
   o->port=0;
   o->active=o->responseReady=FALSE;
}


static int
smc91xdevice(HttpRedirectNode* o,DecodeUrl* sramcsubsys, HttpCommand* cmd)
{
   const char* dn = sramcsubsys->domainName;
   int status;
   if(!dn) return -4;
   status = SoDispCon_connect(&o->cCon, dn, sramcsubsys->port,0,0,1500,FALSE, FALSE,0);
   if(status)
   {
      switch(status)
      {
         case E_CANNOT_RESOLVE:
            HttpResponse_fmtError(
               &cmd->response,
               502,"\122\145\144\151\162\145\143\164\157\162\072\040\103\141\156\156\157\164\040\162\145\163\157\154\166\145\040\144\157\155\141\151\156\040\156\141\155\145\040\042\045\163\042",dn);
            break;
         default:
            HttpResponse_fmtError(
               &cmd->response,
               502,"\122\145\144\151\162\145\143\164\157\162\072\040\103\141\156\156\157\164\040\143\157\156\156\145\143\164\040\164\157\040\042\045\163\072\045\144\042",
               dn,(int)sramcsubsys->port);
      }
   }
   else
   {
      o->domainName = baStrdup(dn);
      o->port=sramcsubsys->port;
      SoDispCon_setReadTmo(&o->cCon,15000);
      if(!o->domainName)
      {
         HttpResponse_sendError1(&cmd->response,503);
         status=E_MALLOC;
      }

   }
   return status;
}


static void
unmapgrant(HttpRedirectNode* o)
{
   SoDispCon_destructor(&o->cCon);
   if(o->domainName)
      baFree(o->domainName);
   DoubleLink_unlink((DoubleLink*)o);
   o->sCon->dispRecEv = o->sConDispEv; 
   if(o->isTerminatedPtr)
      *o->isTerminatedPtr=TRUE;
}


static void
applystate(SoDispCon* con)
{
   HttpRedirectNode* o=(HttpRedirectNode*)((U8*)con-
      offsetof(HttpRedirectNode,cCon));
   if(o->active)
   {
      
      o->responseReady=TRUE;
      SoDisp_deactivateRec(SoDispCon_getDispatcher(con),con);
   }
   else
      SoDispCon_closeCon(con); 
}


static void
l2c310write(SoDispCon* con)
{
   HttpRedirectNode* pn = HttpRedirectNode_find(con);
   if(pn)
   {
      int isTerminated=FALSE;
      pn->isTerminatedPtr = &isTerminated;
      pn->sConDispEv(con);
      if( ! SoDispCon_isValid(con) )
      {
         if( ! isTerminated )
         {
            unmapgrant(pn);
            baFree(pn);
         }
      }
      else if(!isTerminated)
         pn->isTerminatedPtr=0;
      return;
   }
   baAssert(0);
}


